// Üretilen dosya: tool/ozgun/uret.py. Tarih · Fransız Devrimi, Napolyon ve 19. yüzyıl ulus devletleri (kolay).
const ozHistory8Kolay = <(String, String, List<String>, String)>[
  ('Devrim öncesi Fransa\'da toplumun din adamları, soylular ve geri kalan halk olarak üç zümreye ayrıldığı düzene sonradan verilen ad hangisidir?', 'Eski Rejim (Ancien Régime)', ['Restorasyon', 'Direktuvar', 'Temmuz Monarşisi (burjuva krallığı)'], 'Devrimciler 1789 öncesindeki ayrıcalıklara dayalı düzeni \'Eski Rejim\' diye adlandırmıştır. Restorasyon ve Temmuz Monarşisi devrim sonrasına, Direktuvar ise 1795-1799\'a aittir.'),
  ('Eski Rejim Fransa\'sında doğrudan vergi olan taille\'ın yükünü esas olarak hangi kesim taşıyordu?', 'Köylüler ve kentli halktan oluşan üçüncü zümre', ['Yüksek din adamları', 'Saray soyluları', 'Kılıç soyluları ile cübbe soylularının aileleri'], 'Birinci ve ikinci zümre taille\'dan büyük ölçüde muaftı; vergi yükü nüfusun çoğunluğunu oluşturan üçüncü zümrenin omzundaydı.'),
  ('Eski Rejim Fransa\'sında halkın en çok nefret ettiği dolaylı vergilerden biri olan gabelle hangi ürün üzerinden alınırdı?', 'Tuz', ['Şarap', 'Tütün', 'Buğday unu'], 'Gabelle tuz vergisiydi ve bölgeden bölgeye çok farklı oranlarda uygulandığı için kaçakçılığa ve büyük hoşnutsuzluğa yol açıyordu.'),
  ('Fransa\'nın 1780\'lerde içine düştüğü mali bunalımı ağırlaştıran dış etkenlerden biri hangisidir?', 'Amerikan Bağımsızlık Savaşı\'na verilen pahalı destek', ['Otuz Yıl Savaşları\'ndan kalan eski hanedan borçları', 'Kırım Savaşı\'nın masrafları', 'Süveyş Kanalı\'nın inşa giderleri'], 'Fransa, İngiltere\'ye karşı Amerikalı sömürgecileri desteklemek için büyük borçlanmıştı. Bu borçların faizi bütçenin önemli bir bölümünü yutuyordu.'),
  ('1788 kötü hasadının 1789 baharında Fransız kentlerinde yarattığı en doğrudan sonuç hangisidir?', 'Ekmek fiyatlarının çok yükselmesi', ['Ekmek fiyatlarının sert biçimde düşmesi', 'Kentlerden köylere toplu göç', 'Tahıl ihracatının patlaması'], 'Kötü hasat tahıl kıtlığına, bu da ekmek fiyatlarının yükselmesine yol açtı. Kentli yoksulların gelirinin büyük bölümü ekmeğe gidiyordu.'),
  ('Abbé Sieyès\'in 1789 başında yayımladığı ünlü broşürün adı hangisidir?', 'Üçüncü Zümre Nedir?', ['Toplum Sözleşmesi', 'Kanunların Ruhu', 'İnsan Hakları ve Yurttaşlık Üzerine Söylev'], 'Sieyès bu broşürde \'Üçüncü zümre nedir? Her şey. Şimdiye kadar siyasi düzende neydi? Hiçbir şey\' diye sorarak ulusun asıl temsilcisinin üçüncü zümre olduğunu savundu.'),
  ('Etats Généraux 5 Mayıs 1789\'da hangi kentte toplanmıştır?', 'Versay', ['Paris', 'Lyon', 'Reims'], 'Meclis, sarayın bulunduğu Versay\'da toplandı. Bu yüzden Ekim 1789\'a kadar devrimin siyasi olayları büyük ölçüde Versay\'da geçti.'),
  ('Üçüncü zümre temsilcilerinin toplantı salonlarının kapatılması üzerine 20 Haziran 1789\'da bir kapalı spor salonunda anayasa yapmadan dağılmayacaklarına dair ettikleri yemin hangi adla bilinir?', 'Top Oyunu Salonu Yemini', ['Champ de Mars Federasyon Yemini', 'Jakoben Kulübü Yemini', 'Pillnitz Yemini'], 'Jeu de Paume (top oyunu) salonunda yapılan bu yemin, meclisin kralın iradesine karşı kendi varlığını sürdürme kararlılığını simgeler.'),
  ('Bastille baskınından hemen sonra Paris\'te kurulan ve komutanlığına Lafayette\'in getirildiği silahlı yurttaş gücü hangisidir?', 'Ulusal Muhafız', ['İsviçre Muhafızları', 'Büyük Ordu', 'Kraliyet Muhafızı'], 'Ulusal Muhafız, düzeni korumak ve devrimi savunmak için oluşturulan burjuva milis gücüdür; ilk komutanı Lafayette\'tir.'),
  ('1789 yazında Fransız kırsalında soyluların köylülere saldıracağı söylentileriyle yayılan panik ve şato yağmaları dalgasına ne ad verilir?', 'Büyük Korku', ['Beyaz Terör', 'Haziran Günleri', 'Eylül Katliamları'], 'Temmuz-Ağustos 1789\'daki Büyük Korku sırasında köylüler senyörlerin şatolarına saldırıp feodal yükümlülükleri gösteren belgeleri yaktılar.'),
  ('Ulusal Meclis\'in 4 Ağustos 1789 gecesi aldığı kararların temel içeriği hangisidir?', 'Feodal ayrıcalıkların kaldırılması', ['Kilise topraklarının papalığa geri verilmesi', 'Kralın tahttan indirilip cumhuriyetin ilan edilmesi', 'Avusturya\'ya savaş açılması'], 'Kırsaldaki isyanları yatıştırmak isteyen meclis, 4 Ağustos gecesi feodal hakları, vergi muafiyetlerini ve öşrü kaldırma kararı aldı.'),
  ('Ekim 1789\'da ekmek pahalılığına öfkelenen Parisli kadınların Versay\'a yürümesinin sonucu hangisidir?', 'Kral ailesinin Paris\'e, Tuileries Sarayı\'na taşınması', ['Kralın Avusturya\'ya kaçıp orada sürgün hükümeti kurması', 'Ulusal Meclis\'in dağıtılması', 'Bastille\'in yıkılması'], '5-6 Ekim 1789 yürüyüşü, kralı ve ailesini Paris\'e gelmeye zorladı. Meclis de kısa süre sonra Paris\'e taşındı ve kral halkın denetimi altına girdi.'),
  ('Kilise topraklarının güvencesiyle çıkarılan, zamanla kâğıt para gibi kullanılıp büyük enflasyona yol açan belgelere ne ad verilir?', 'Assignat', ['Livre tournois', 'Frank germinal', 'Sou'], 'Assignat\'lar başta faizli bono olarak çıkarıldı, sonra paraya dönüştü. Aşırı basım nedeniyle 1790\'ların ortasında değerinin çok büyük bölümünü kaybetti.'),
  ('Kurucu Meclis\'in 1790\'da eski eyaletleri kaldırarak Fransa\'yı birbirine yakın büyüklükteki yönetim birimlerine ayırdığı yeni bölüm hangisidir?', 'Departman', ['Kanton', 'Bölge valiliği', 'Prenslik'], 'Fransa 83 departmana bölündü. Bu düzen, eski eyaletlerin farklı ayrıcalıklarını ortadan kaldırarak tek tip bir yönetim kurdu.'),
  ('1791 Fransız Anayasası\'nın kurduğu yönetim biçimi hangisidir?', 'Anayasal (meşruti) monarşi', ['Mutlak monarşi', 'Askerî diktatörlük', 'Cumhuriyet'], '1791 Anayasası kralı tahtta bıraktı, ancak yasama yetkisini seçilmiş bir meclise verdi ve krala yalnız erteleyici veto tanıdı.'),
  ('Haziran 1791\'de kılık değiştirerek kaçmaya çalışan XVI. Louis ve ailesinin tanınıp yakalandığı kasaba hangisidir?', 'Varennes', ['Valmy', 'Sedan', 'Verdun'], 'Kraliyet ailesi doğu sınırına ulaşmaya çalışırken Varennes\'de durduruldu ve Paris\'e geri getirildi.'),
  ('Varennes kaçışının Fransız kamuoyu üzerindeki en önemli etkisi hangisidir?', 'Krala duyulan güvenin sarsılması ve cumhuriyetçi düşüncenin güçlenmesi', ['Kralın halk arasında daha çok sevilmesi', 'Avusturya ile kalıcı bir barış ve ittifak antlaşması yapılması', 'Ruhban Sivil Anayasası\'nın kaldırılması'], 'Kralın devrimi kabul etmediği ortaya çıktı. Anayasal monarşinin dayanağı zayıfladı ve cumhuriyet talebi yüksek sesle dile getirilmeye başlandı.'),
  ('Devrim sırasında Fransa\'dan kaçıp yurt dışında, özellikle Koblenz\'de karşı devrim için örgütlenen soylulara ne ad verilir?', 'Göçmenler (émigrés)', ['Sans-culotte\'lar', 'Jirondenler', 'Feuillant\'lar (anayasal kraliyetçiler)'], 'Émigrés, Avrupa sarayları nezdinde devrime karşı müdahale istedi. Meclis onların mallarına el koyarak karşılık verdi.'),
  ('Nisan 1792\'de Yasama Meclisi\'nin savaş ilan ettiği ilk devlet hangisidir?', 'Avusturya', ['İngiltere ve Hollanda', 'İspanya', 'Rusya'], '20 Nisan 1792\'de Fransa, Avusturya\'ya (Bohemya ve Macaristan kralına) savaş açtı; Prusya kısa süre sonra Avusturya\'nın yanında savaşa girdi.'),
  ('Marsilya\'dan gelen gönüllülerin Paris\'e girerken söylediği ve sonradan Fransa\'nın ulusal marşı olan şarkı hangisidir?', 'La Marseillaise', ['Ça ira', 'Le Chant du départ', 'La Carmagnole'], 'Rouget de Lisle\'in 1792\'de Strazburg\'da yazdığı Ren Ordusu savaş şarkısı, Marsilyalı federelerin söylemesiyle \'La Marseillaise\' adını aldı.'),
  ('Eylül 1792\'nin başında yabancı orduların Paris\'e yaklaştığı haberleri üzerine hapishanelerdeki tutukluların kalabalıklar tarafından öldürüldüğü olaylar hangi adla bilinir?', 'Eylül Katliamları', ['Büyük Korku', 'Beyaz Terör', 'Kanlı Hafta'], 'Tutukluların düşmanla iş birliği yapacağı korkusu, 2-6 Eylül 1792\'de bin kadar kişinin yargısız öldürülmesine yol açtı.'),
  ('20 Eylül 1792\'de Fransız ordusunun Prusya ordusunu durdurduğu ve Goethe\'nin \'Burada ve bugün dünya tarihinde yeni bir çağ başlıyor\' dediği aktarılan savaş hangisidir?', 'Valmy', ['Jemappes', 'Fleurus', 'Neerwinden'], 'Valmy\'deki top düellosunda Prusyalılar geri çekildi. Ertesi gün Konvansiyon toplandı ve monarşiyi kaldırdı.'),
  ('Fransa\'da monarşi resmen hangi yıl kaldırılıp cumhuriyet ilan edilmiştir?', '1792', ['1789', '1793', '1799'], 'Ulusal Konvansiyon 21 Eylül 1792\'de monarşiyi kaldırdı; ertesi gün belgeler \'Cumhuriyetin I. Yılı\' diye tarihlenmeye başladı.'),
  ('XVI. Louis\'yi ihanetle suçlayarak Ocak 1793\'te ölüm cezasına çarptıran kurum hangisidir?', 'Ulusal Konvansiyon', ['Paris Parlementosu ve kraliyet danışma meclisi', 'Devrim Mahkemesi', 'Direktuvar'], 'Kral, Konvansiyon üyelerinin tek tek açık oylamasıyla yargılandı ve küçük bir çoğunlukla idama mahkûm edildi; 21 Ocak 1793\'te giyotinle idam edildi.'),
  ('XVI. Louis\'nin eşi Marie-Antoinette hangi hanedandan geliyordu?', 'Habsburg', ['Hohenzollern', 'Romanov', 'Stuart'], 'Marie-Antoinette, Avusturya İmparatoriçesi Maria Theresia\'nın kızıydı. Fransızlar arasında \'Avusturyalı kadın\' diye anılması bu kökene dayanır.'),
  ('Marie-Antoinette hangi yıl giyotinle idam edilmiştir?', '1793', ['1791', '1795', '1789'], 'Kraliçe, kocasından yaklaşık dokuz ay sonra, Ekim 1793\'te Devrim Mahkemesi kararıyla idam edildi.'),
  ('Konvansiyon\'da salonun üst sıralarında oturan, Robespierre, Danton ve Marat gibi radikal temsilcilerin oluşturduğu gruba ne ad verilirdi?', 'Dağlılar (Montagnards)', ['Ova (Plaine ya da Marais)', 'Jirondenler', 'Feuillant\'lar'], 'Dağlılar adını meclisin yüksek sıralarında oturmalarından aldı. Paris\'in halk kesimlerine dayanıyorlardı.'),
  ('Diz altında biten soylu pantolonu yerine uzun pantolon giydikleri için adlandırılan Parisli zanaatkâr ve küçük esnaf kesimine ne ad verilir?', 'Sans-culotte\'lar', ['Muscadin\'ler', 'Chouan\'lar', 'Federeler'], 'Sans-culotte \'kısa pantolonsuz\' demektir. Bu kesim fiyat denetimi ve doğrudan demokrasi talepleriyle Paris siyasetini etkiledi.'),
  ('Terör döneminde fiilen hükümet gibi çalışan ve üyeleri arasında Robespierre, Saint-Just ve Carnot\'nun bulunduğu kurul hangisidir?', 'Kamu Selameti Komitesi', ['Genel Güvenlik Komitesi', 'Beşyüzler Meclisi', 'Devlet Konseyi'], 'Konvansiyon\'un 1793\'te kurduğu Kamu Selameti Komitesi savaşı, ekonomiyi ve iç güvenliği yöneten en güçlü organ hâline geldi.'),
  ('Devrim döneminde Batı Fransa\'da, özellikle zorunlu askere alma ve din politikalarına tepki olarak 1793\'te patlak veren büyük kraliyetçi-katolik köylü ayaklanması hangisidir?', 'Vendée isyanı', ['Büyük Korku', 'Federasyon Bayramı', 'Lyon kuşatması'], 'Mart 1793\'te 300 bin kişilik asker toplama kararı Vendée\'de isyanı başlattı; cumhuriyet orduları bölgeyi büyük bir şiddetle bastırdı.'),
  ('\'Halkın Dostu\' (L\'Ami du peuple) gazetesini çıkaran ve 1793\'te banyo küvetindeyken öldürülen radikal gazeteci kimdir?', 'Jean-Paul Marat', ['Camille Desmoulins', 'Jacques Hébert', 'Georges Danton'], 'Marat 13 Temmuz 1793\'te Jiroden yanlısı Charlotte Corday tarafından bıçaklanarak öldürüldü; David\'in \'Marat\'nın Ölümü\' tablosu bu olayı konu alır.'),
  ('1792\'de adalet bakanı olan, Eylül 1792\'de \'Cesaret, daha çok cesaret, her zaman cesaret!\' sözüyle halkı savaşa çağıran ve 1794\'te giyotinle idam edilen devrimci kimdir?', 'Georges Danton', ['Maximilien Robespierre', 'Jean-Paul Marat', 'Saint-Just'], 'Danton 1794 başında Terör\'ün yumuşatılmasını savunan \'Hoşgörülüler\' arasında yer aldı ve Nisan 1794\'te Robespierre\'in onayıyla idam edildi.'),
  ('1791\'de \'Kadın ve Kadın Yurttaş Hakları Bildirisi\'ni yayımlayan ve 1793\'te giyotinle idam edilen yazar kimdir?', 'Olympe de Gouges', ['Madame Roland', 'Madame de Staël', 'Théroigne de Méricourt'], 'Olympe de Gouges, 1789 bildirisinin kadınları dışarıda bıraktığını eleştirerek kadınlara eşit haklar istedi.'),
  ('Hem Amerikan Bağımsızlık Savaşı\'nda savaşan hem de 1789\'da Ulusal Muhafız\'ın komutanı olan Fransız soylu kimdir?', 'Lafayette Markisi', ['Honoré Gabriel Riqueti, Mirabeau Kontu', 'Rochambeau Kontu', 'Brunswick Dükü'], 'Lafayette \'iki dünyanın kahramanı\' diye anıldı. 1792\'de devrim radikalleşince Avusturyalılara sığındı ve yıllarca tutuklu kaldı.'),
  ('Bir belge \'Cumhuriyetin II. Yılı, 9 Thermidor\' tarihini taşımaktadır. Bu tarihte yaşanan olay hangisidir?', 'Robespierre\'in Konvansiyon\'da düşürülmesi', ['Bastille\'in alınması', 'Napolyon\'un Direktuvar\'a karşı yaptığı darbe', 'Kralın idamı'], '9 Thermidor II. Yıl, 27 Temmuz 1794\'e denk gelir; Robespierre ve yandaşları bu tarihte tutuklandı, ertesi gün idam edildi.'),
  ('Robespierre\'in Haziran 1794\'te bizzat yönettiği ve ateist Hristiyanlıktan arındırma akımına karşı düzenlenen tören hangi kültle ilgilidir?', 'Yüce Varlık Kültü', ['Akıl Kültü', 'Teofilantropi', 'Gallikanizm'], 'Robespierre ateizmi aristokratik sayıyordu. Tanrının varlığına ve ruhun ölümsüzlüğüne dayanan bir sivil din olarak Yüce Varlık Kültü\'nü kurdu.'),
  ('Devrim döneminde Fransız bilim insanlarının geliştirdiği ve uzunluk birimini Dünya meridyeninin belli bir kesrine dayandıran ölçü sistemi hangisidir?', 'Metrik sistem', ['Emperyal sistem', 'Altmışlık sistem', 'Troy ölçü sistemi'], 'Metre, Kuzey Kutbu ile Ekvator arasındaki meridyen yayının on milyonda biri olarak tanımlandı; amaç yerel ölçü karmaşasına son vermekti.'),
  ('Robespierre\'in düşüşünden sonra güneydoğu Fransa\'da Jakobenlere ve devrimcilere yönelik intikam şiddetine ne ad verilir?', 'Beyaz Terör', ['Kızıl Terör', 'Büyük Korku', 'Kanlı Pazar'], '1795\'teki Beyaz Terör\'de kraliyetçiler ve ılımlılar eski Jakobenlere saldırdı. \'Beyaz\' renk Bourbon monarşisini çağrıştırır.'),
  ('1795\'te kabul edilen Yıl III Anayasası yürütme gücünü kime vermiştir?', 'Beş kişilik Direktuvar\'a', ['Tek bir krala', 'Birinci konsüle', 'Kamu Selameti Komitesi\'ne'], 'Tek kişinin diktatörlüğünden korkan Thermidorcular yürütmeyi beş direktöre böldü. Bu yüzden rejime Direktuvar denir.'),
  ('Napolyon Bonapart hangi adada doğmuştur?', 'Korsika', ['Sardinya', 'Sicilya', 'Elba'], 'Napolyon 1769\'da Korsika\'nın Ajaccio kentinde doğdu. Ada, doğumundan kısa süre önce Cenova\'dan Fransa\'ya geçmişti.'),
  ('Genç topçu subayı Napolyon\'un adını ilk kez duyurduğu, 1793\'te İngilizlerin desteklediği kraliyetçilerden geri alınan liman kenti hangisidir?', 'Toulon', ['Marsilya', 'Brest', 'Bordeaux'], 'Toulon kuşatmasında topçuyu başarıyla yerleştiren Napolyon, 24 yaşında tuğgeneralliğe yükseltildi.'),
  ('Napolyon\'un 1796\'da evlendiği, eski kocası Terör döneminde idam edilmiş olan kadın kimdir?', 'Joséphine de Beauharnais', ['Marie-Louise', 'Désirée Clary', 'Pauline Borghese'], 'Joséphine\'in ilk eşi Alexandre de Beauharnais 1794\'te giyotinlenmişti. Napolyon, varis doğuramadığı gerekçesiyle 1809\'da ondan boşandı.'),
  ('Napolyon\'un Mısır seferi sırasında, Ağustos 1798\'de Fransız donanmasını Ebukır Körfezi\'nde yok eden İngiliz amiral kimdir?', 'Horatio Nelson', ['Arthur Wellesley', 'John Jervis', 'Cuthbert Collingwood'], 'Nil Savaşı (Ebukır deniz savaşı) ile Nelson Fransız filosunu imha etti ve Napolyon\'un ordusu Mısır\'da mahsur kaldı.'),
  ('Napolyon\'un Kasım 1799\'da Direktuvar\'ı deviren darbesi hangi tarih adıyla anılır?', '18 Brumaire', ['13 Vendémiaire', '9 Thermidor', '1 Prairial'], '18-19 Brumaire VIII. Yıl (9-10 Kasım 1799) darbesiyle Direktuvar yıkıldı ve Konsüllük kuruldu.'),
  ('18 Brumaire darbesini Napolyon ile birlikte planlayan, 1789\'da ünlü bir broşürün de yazarı olan direktör kimdir?', 'Sieyès', ['Paul Barras', 'Carnot', 'Fouché'], 'Sieyès güçlü bir yürütme kurmak için bir generale ihtiyaç duyuyordu; ancak darbeden sonra Napolyon onu kısa sürede geri plana itti.'),
  ('1799 Konsüllük Anayasası\'nda gerçek yetki kimde toplanmıştır?', 'Birinci konsülde', ['Üç konsülde eşit olarak', 'Senatoda', 'Yasama Kurulu\'nda'], 'Anayasa üç konsül öngörse de ikinci ve üçüncü konsül yalnız danışma yetkisine sahipti; bütün yürütme gücü Birinci Konsül Napolyon\'daydı.'),
  ('Napolyon\'un rejimini meşrulaştırmak için anayasa, ömür boyu konsüllük ve imparatorluk konularında başvurduğu oylama yöntemi hangisidir?', 'Plebisit', ['Zümre esaslı oylama', 'Mecliste gizli oylama', 'Seçici prensler oylaması'], '1800, 1802 ve 1804 plebisitleri ezici \'evet\' sonuçlarıyla rejimi halk onayına dayandırdı; ancak sonuçların şişirildiği bilinmektedir.'),
  ('1800\'de kurulan ve para basma yetkisini zamanla tek başına üstlenen Fransız kurumu hangisidir?', 'Fransa Bankası', ['Fransa Doğu Hindistan Şirketi', 'Paris Borsası', 'Crédit Mobilier'], 'Banque de France, Napolyon\'un mali istikrar politikasının parçası olarak 1800\'de kuruldu ve 1803\'te Paris\'te banknot basma tekeli aldı.'),
  ('Napolyon\'un 1801\'de Papa VII. Pius ile imzaladığı ve devrimin Kilise ile açtığı yarayı kapatmayı amaçlayan anlaşmaya ne ad verilir?', 'Konkordato', ['Pragmatik Yaptırım', 'Nantes Fermanı', 'Ruhban Sivil Anayasası'], 'Konkordato Katolikliği \'Fransızların çoğunluğunun dini\' olarak tanıdı; Kilise de devrimde satılan mülklerini geri istememeyi kabul etti.'),
  ('Napolyon\'un 1802\'de askerî ve sivil hizmetleri ödüllendirmek için kurduğu nişan hangisidir?', 'Lejyon d\'Onör', ['Altın Post Nişanı', 'Dizbağı Nişanı', 'Demir Haç'], 'Légion d\'honneur, doğuma değil hizmete dayalı bir onur düzeni olarak kuruldu ve bugün de Fransa\'nın en yüksek nişanıdır.'),
  ('Napolyon Kanunu\'nun (1804) aile hukukunda kadının konumuna ilişkin hükümleri için hangisi doğrudur?', 'Kadını kocasının otoritesine bağlı kıldı', ['Kadınlara tam siyasi eşitlik tanıdı', 'Kadınlara seçme ve seçilme hakkı verdi', 'Kadınların mülkiyet hakkını kocalarınkinden üstün tuttu'], 'Medeni Kanun \'koca karısını korur, kadın kocasına itaat eder\' anlayışını benimsedi; kadının mülkünü yönetme hakkı büyük ölçüde kocaya verildi.'),
  ('Napolyon\'un 1800\'de Alpleri aşarak Avusturyalılara karşı kazandığı ve Konsüllük rejimini sağlamlaştıran zafer hangisidir?', 'Marengo', ['Wagram', 'Eylau', 'Lützen'], 'Haziran 1800\'deki Marengo zaferi, başlangıçta kaybedilmek üzereyken General Desaix\'in yetişmesiyle kazanıldı; Desaix savaşta öldü.'),
  ('Napolyon 2 Aralık 1804\'te imparatorluk tacını hangi yapıda giymiştir?', 'Notre-Dame Katedrali', ['Reims Katedrali', 'Versay Sarayı', 'Saint-Denis Bazilikası'], 'Fransız kralları geleneksel olarak Reims\'te taç giyerdi. Napolyon, Bourbon geleneğinden ayrılarak Paris\'teki Notre-Dame\'ı seçti.'),
  ('Napolyon\'un taç giyme törenini büyük bir tabloyla resmeden saray ressamı kimdir?', 'Jacques-Louis David', ['Eugène Delacroix', 'Francisco Goya', 'Théodore Géricault'], 'David\'in \'Napolyon\'un Taç Giymesi\' tablosu Louvre\'dadır. David devrim döneminde de \'Marat\'nın Ölümü\' gibi siyasi eserler yapmıştı.'),
  ('Napolyon\'un mareşalleri arasında Rusya\'dan çekilişte artçı birlikleri yönettiği için \'cesurların en cesuru\' diye anılan, 1815\'te kurşuna dizilen kişi kimdir?', 'Michel Ney', ['Joachim Murat', 'Jean-Baptiste Bernadotte', 'André Masséna'], 'Ney, Yüz Gün\'de Napolyon\'a katıldı ve Waterloo\'da süvari saldırılarını yönetti; Bourbonlar döneminde vatana ihanetten idam edildi.'),
  ('Napolyon\'un 1806\'da Batı ve Güney Almanya devletlerini kendi koruması altında topladığı birlik hangisidir?', 'Ren Konfederasyonu', ['Alman Konfederasyonu', 'Kuzey Alman Konfederasyonu', 'Hansa Birliği'], 'Ren Konfederasyonu\'na Bavyera, Württemberg, Baden gibi devletler katıldı; bu devletler Fransa\'ya asker sağlamayı üstlendi.'),
  ('Ekim 1806\'da Prusya ordusunun aynı gün iki ayrı savaşta ağır yenilgiye uğradığı muharebeler hangileridir?', 'Jena ve Auerstedt', ['Ulm ve Austerlitz', 'Eylau ve Friedland', 'Lützen ve Bautzen'], '14 Ekim 1806\'da Napolyon Jena\'da, Mareşal Davout Auerstedt\'te Prusyalıları yendi; birkaç hafta içinde Berlin işgal edildi.'),
  ('Napolyon ile Rus Çarı I. Aleksandr\'ın 1807\'de Neman Irmağı üzerindeki bir salda görüştükten sonra imzaladıkları antlaşma hangisidir?', 'Tilsit Antlaşması', ['Pressburg Antlaşması', 'Lunéville Antlaşması', 'Schönbrunn Antlaşması'], 'Tilsit\'te Rusya Kıta Ablukası\'na katılmayı kabul etti; Prusya ise topraklarının yaklaşık yarısını kaybetti.'),
  ('Tilsit Antlaşması\'ndan sonra Prusya\'nın Polonya topraklarından kurulan ve Saksonya kralına bağlanan devlet hangisidir?', 'Varşova Dükalığı', ['Kongre Polonyası', 'Galiçya Krallığı', 'Kraków Cumhuriyeti'], 'Varşova Dükalığı, Polonyalıların bağımsızlık umutlarını canlandırdı; bu yüzden pek çok Polonyalı Napolyon\'un ordusunda savaştı.'),
  ('Napolyon\'un seçkin askerlerden oluşan, savaşlarda genellikle son yedek olarak tuttuğu birlik hangisidir?', 'İmparatorluk Muhafızı', ['İsviçre Muhafızı', 'Ulusal Muhafız', 'Kızıl Gömlekliler'], 'Garde impériale en deneyimli askerlerden oluşuyordu. Waterloo\'da Muhafız\'ın geri çekilmesi Fransız ordusunun dağılmasının işareti oldu.'),
  ('Kıta Ablukası\'nı başlatan kararname 1806\'da hangi kentte ilan edilmiştir?', 'Berlin', ['Viyana', 'Milano', 'Varşova'], 'Napolyon, Prusya\'yı yendikten sonra Kasım 1806\'da Berlin Kararnamesi\'ni yayımladı; 1807\'deki Milano Kararnamesi ablukayı sertleştirdi.'),
  ('Kıta Ablukası\'na katılmayı reddettiği için 1807\'de Fransız ordusunca işgal edilen, kraliyet ailesinin Brezilya\'ya kaçtığı ülke hangisidir?', 'Portekiz', ['Danimarka', 'İsveç', 'Sicilya'], 'Portekiz İngiltere\'nin eski müttefikiydi. Junot\'un işgali üzerine Braganza hanedanı İngiliz donanmasının korumasında Rio de Janeiro\'ya geçti.'),
  ('Napolyon\'un ağabeyi Joseph Bonaparte\'ı 1808\'de kral yaptığı ve yoğun bir halk direnişiyle karşılaştığı ülke hangisidir?', 'İspanya', ['İsveç', 'Portekiz', 'Polonya'], 'Napolyon, İspanyol Bourbonlarını Bayonne\'da tahttan feragat etmeye zorladı ve Joseph\'i kral yaptı. Bu karar ülkeyi genel bir ayaklanmaya sürükledi.'),
  ('2 Mayıs 1808\'de Madrid halkının Fransız birliklerine karşı ayaklanması ve ertesi gün yapılan toplu kurşuna dizmeleri anlatan ünlü tabloların ressamı kimdir?', 'Francisco Goya', ['Diego Velázquez', 'El Greco', 'Bartolomé Murillo'], 'Goya\'nın \'2 Mayıs 1808\' ve \'3 Mayıs 1808\' tabloları savaşın vahşetini yansıtan eserler olarak kabul edilir; Goya ayrıca \'Savaşın Felaketleri\' gravürlerini yaptı.'),
  ('\'Küçük savaş\' anlamına gelen ve İspanyol halkının düzenli ordu yerine küçük gruplarla Fransızları yıpratmasından dünya dillerine geçen sözcük hangisidir?', 'Gerilla', ['Partizan', 'Komando', 'Milis'], 'Guerrilla, İspanyolcada \'küçük savaş\' demektir. Yarımada Savaşı\'ndaki halk direnişi bu adın evrenselleşmesini sağladı.'),
  ('Napolyon\'un Avusturya\'yı 1809\'da Viyana yakınlarında yendiği büyük savaş hangisidir?', 'Wagram', ['Austerlitz', 'Marengo', 'Ulm'], 'Temmuz 1809\'daki Wagram zaferinden sonra Avusturya Schönbrunn Antlaşması\'nı imzalamak zorunda kaldı.'),
  ('Napolyon\'un Joséphine\'den boşandıktan sonra 1810\'da evlendiği, Avusturya imparatorunun kızı olan prenses kimdir?', 'Marie-Louise', ['Maria Theresia', 'Marie-Caroline', 'Hortense'], 'Bu evlilik Avusturya ile ilişkileri yumuşatmak ve hanedana varis sağlamak içindi; 1811\'de oğulları \'Roma Kralı\' doğdu.'),
  ('Napolyon\'un 1812\'de Rusya\'ya saldırmasının başlıca nedeni hangisidir?', 'Çar I. Aleksandr\'ın Kıta Ablukası\'ndan ayrılması', ['Rusya\'nın Fransa\'ya Moskova\'dan savaş ilan edip Paris\'e yürümesi', 'Rusya\'nın İspanya\'yı işgal etmesi', 'Rusya\'nın Osmanlı ile ittifak kurup Mısır\'ı alması'], 'Abluka Rus ekonomisine zarar veriyordu. Rusya 1810\'dan itibaren tarafsız gemilere limanlarını açtı ve Fransız mallarına gümrük koydu.'),
  ('Eylül 1812\'de Moskova\'nın batısında yapılan ve tek günde on binlerce askerin öldüğü kanlı savaş hangisidir?', 'Borodino', ['Smolensk', 'Berezina', 'Austerlitz'], 'Borodino\'da Ruslar geri çekildi ama ordularını korudu; bir hafta sonra Napolyon boşaltılmış Moskova\'ya girdi.'),
  ('1812\'de Rus ordusunun başkomutanı olan ve meydan savaşından kaçınıp Fransızları yıpratma stratejisiyle bilinen yaşlı general kimdir?', 'Mihail Kutuzov', ['Aleksandr Suvorov', 'Pyotr Bagration', 'Barclay de Tolly'], 'Kutuzov Borodino\'dan sonra Moskova\'yı savaşmadan bıraktı; Fransızların geri çekilişini sürekli taciz ederek ordunun çözülmesini hızlandırdı.'),
  ('Kasım 1812\'de geri çekilen Fransız ordusunun büyük kayıplar vererek köprülerle geçtiği ve adı Fransızcada felaket anlamında kullanılan ırmak hangisidir?', 'Berezina', ['Neman', 'Don', 'Moskova'], 'Pontonculuk birliklerinin donan sularda kurduğu köprüler sayesinde ordunun bir kısmı kurtuldu; Fransızcada \'c\'est la Bérézina\' ifadesi büyük felaket anlamına gelir.'),
  ('Tolstoy\'un 1812 Fransız istilasını ve Rus toplumunu anlatan büyük romanı hangisidir?', 'Savaş ve Barış', ['Anna Karenina adlı uzun roman', 'Suç ve Ceza', 'Ölü Canlar'], 'Savaş ve Barış, Austerlitz\'den Borodino\'ya ve Moskova yangınına kadar Napolyon savaşlarını Rus aristokrat aileleri üzerinden anlatır.'),
  ('Ekim 1813\'te Napolyon\'un Rusya, Prusya, Avusturya ve İsveç\'in ortak ordularına yenildiği ve \'Uluslar Savaşı\' olarak anılan muharebe hangisidir?', 'Leipzig', ['Dresden', 'Bautzen', 'Waterloo'], 'Leipzig, Waterloo\'dan önce Avrupa\'nın en büyük meydan savaşıydı. Yenilgiden sonra Ren Konfederasyonu dağıldı ve Napolyon Fransa\'ya çekildi.'),
  ('Leipzig Savaşı\'nın \'Uluslar Savaşı\' diye anılmasının nedeni nedir?', 'Pek çok Avrupa ulusundan askerin iki tarafta da savaşması', ['Savaşın bir deniz savaşı olması', 'Savaşın yalnızca iki ülke arasında geçmesi', 'Savaşın büyük güçlerin katıldığı bir barış konferansında karara bağlanması'], 'Fransız tarafında Polonyalı, İtalyan ve Alman birlikler; karşı tarafta Rus, Prusyalı, Avusturyalı ve İsveçli birlikler savaştı.'),
  ('Müttefik orduları Paris\'e hangi yıl girmiştir?', '1814', ['1813', '1815', '1812'], 'Müttefikler 31 Mart 1814\'te Paris\'e girdi. Napolyon Nisan 1814\'te Fontainebleau\'da tahttan çekildi.'),
  ('Napolyon\'un Nisan 1814\'te tahttan çekildiği antlaşmayla kendisine verilen yer hangisidir?', 'Elba Adası', ['Saint Helena Adası', 'Korsika Adası', 'Malta Adası'], 'Fontainebleau Antlaşması Napolyon\'a imparator unvanını bırakarak küçük Elba Adası\'nın egemenliğini verdi.'),
  ('Napolyon\'un ilk düşüşünden sonra Fransa tahtına geçen Bourbon kralı kimdir?', 'XVIII. Louis', ['X. Charles', 'XVII. Louis', 'Louis-Philippe'], 'XVI. Louis\'nin kardeşi olan XVIII. Louis 1814\'te tahta geçti. XVII. Louis, 1795\'te çocuk yaşta tutuklulukta ölen veliahta verilen unvandır.'),
  ('Waterloo\'dan sonra Napolyon\'un sürgün edildiği ve 1821\'de öldüğü yer hangisidir?', 'Saint Helena Adası', ['Elba Adası', 'Malta Adası', 'Sicilya Adası'], 'Güney Atlas Okyanusu\'ndaki İngiliz adası Saint Helena, Avrupa\'dan çok uzak olduğu için seçildi; Napolyon 5 Mayıs 1821\'de burada öldü.'),
  ('Viyana Kongresi\'nde yenik Fransa\'yı temsil ettiği hâlde ustaca diplomasisiyle ülkesini büyük güçler arasına geri sokan Fransız diplomat kimdir?', 'Talleyrand', ['Fouché', 'Richelieu', 'Chateaubriand'], 'Talleyrand, galiplerin arasındaki Saksonya-Polonya anlaşmazlığından yararlandı ve meşruiyet ilkesini öne sürerek Fransa\'yı müzakerelere eşit ortak olarak kattı.'),
  ('Viyana Kongresi\'nin Fransız Devrimi öncesindeki hanedanları tahtlarına geri getirmeyi öngören ilkesi hangisidir?', 'Meşruiyet', ['Ulusların kendi kaderini tayini', 'Halk egemenliği', 'Doğal sınırlar'], 'Meşruiyet ilkesiyle Fransa, İspanya ve Napoli\'de Bourbonlar, diğer yerlerde de eski hanedanlar tahtlarına döndü.'),
  ('Viyana Kongresi\'nde kurulan ve 39 egemen devlet ile özgür kentten oluşan gevşek yapı hangisidir?', 'Alman Konfederasyonu', ['Ren Konfederasyonu', 'Kuzey Alman Konfederasyonu', 'Zollverein'], 'Deutscher Bund\'un Frankfurt\'ta toplanan bir Federal Meclisi vardı ve başkanlığını Avusturya yürütüyordu; ortak bir hükümeti yoktu.'),
  ('Viyana Kongresi\'nde sonuna kadar Napolyon\'un müttefiki kalan Danimarka\'dan alınıp İsveç\'e bağlanan ülke hangisidir?', 'Norveç', ['Finlandiya', 'İzlanda', 'Pomeranya'], 'İsveç, Rusya\'ya kaptırdığı Finlandiya\'ya karşılık Norveç\'i aldı (1814 Kiel Antlaşması, Viyana\'da onaylandı). Norveç 1905\'te bağımsızlığını kazandı.'),
  ('Çar I. Aleksandr\'ın önerisiyle 1815\'te Rusya, Avusturya ve Prusya hükümdarlarının Hristiyan ilkelerine göre hareket etmeyi taahhüt ettikleri bildiri hangisidir?', 'Kutsal İttifak', ['Dörtlü İttifak', 'Üç İmparator Ligi', 'Reasürans Antlaşması'], 'Kutsal İttifak somut yükümlülükler içermeyen bir ilke bildirgesiydi; Castlereagh onu \'yüce bir mistisizm ve saçmalık parçası\' diye niteledi.'),
  ('Metternich\'in 1815 sonrasında izlediği politikanın temel amacı hangisidir?', 'Liberal ve ulusçu hareketleri bastırarak mevcut düzeni korumak', ['Avrupa\'da cumhuriyetleri yaygınlaştırmak ve genel oyu yerleştirmek', 'Avusturya\'yı ulusal bir devlete dönüştürmek', 'İtalya ve Almanya\'nın birliğini sağlamak'], 'Çok uluslu Avusturya için ulusçuluk varoluşsal bir tehditti; Metternich bu yüzden sansür, polis ve askerî müdahaleye dayanan muhafazakâr bir sistem kurdu.'),
  ('1822 Verona Kongresi\'nin kararıyla 1823\'te İspanya\'ya ordu göndererek VII. Fernando\'nun mutlak yönetimini geri getiren devlet hangisidir?', 'Fransa', ['Avusturya', 'Prusya', 'İngiltere'], '\'Saint Louis\'nin Yüz Bin Oğlu\' diye anılan Fransız ordusu, Trocadero\'da liberalleri yendi. Bu müdahale Bourbon Fransası\'nın kongre sistemine bağlılığını gösterdi.'),
  ('Aralık 1825\'te Çar I. Aleksandr\'ın ölümünün ardından Petersburg\'da anayasa ve reform isteyen subayların başlattığı başarısız ayaklanma hangisidir?', 'Dekabrist Ayaklanması', ['Pugaçev Ayaklanması', 'Kronştat Ayaklanması', 'Kanlı Pazar'], 'Adını Rusça \'Aralık\' (dekabr) sözcüğünden alır. Napolyon savaşlarında Batı\'yı gören liberal subaylar tarafından başlatıldı ve I. Nikola tarafından bastırıldı.'),
  ('1824\'te XVIII. Louis\'nin yerine geçen ve aşırı kraliyetçi politikalarıyla 1830 devrimine yol açan Fransa kralı kimdir?', 'X. Charles', ['Louis-Philippe I', 'Berry Dükü', 'III. Napolyon'], 'Eski Artois Kontu olan X. Charles, Reims\'te geleneksel törenle taç giydi ve göçmen soylulara tazminat ödenmesi gibi uygulamalarla liberalleri öfkelendirdi.'),
  ('Paris\'te 27-29 Temmuz 1830\'da yaşanan ve X. Charles\'ı tahttan indiren üç günlük ayaklanmaya Fransızlar ne ad verir?', 'Üç Şanlı Gün (Trois Glorieuses)', ['Haziran Günleri (Journées de Juin)', 'Kanlı Hafta', 'Büyük Korku'], 'Üç günlük sokak çatışmalarından sonra kral kaçmak zorunda kaldı; Paris\'te Temmuz Sütunu bu olayların anısına dikildi.'),
  ('Delacroix\'nın \'Halka Yol Gösteren Özgürlük\' tablosu hangi olayı konu alır?', '1830 Temmuz Devrimi', ['Bastille\'in alınması', '1848 Şubat Devrimi', 'Paris Komünü'], 'Tablo 1830\'da yapıldı ve elinde üç renkli bayrakla barikatlarda ilerleyen kadın figürüyle özgürlüğü simgeler; çoğu kez yanlışlıkla 1789 ile ilişkilendirilir.'),
  ('1830 devriminden sonra tahta çıkan ve \'Fransızların Kralı\' unvanını kullanan Orléans hanedanı üyesi kimdir?', 'Louis-Philippe', ['X. Charles', 'Henri de Chambord', 'XVIII. Louis'], 'Louis-Philippe \'Fransa Kralı\' yerine \'Fransızların Kralı\' unvanını alarak gücünü ulustan aldığını vurguladı; üç renkli bayrağı da yeniden benimsedi.'),
  ('Temmuz Monarşisi\'nin (1830-1848) toplumsal dayanağı en çok hangi kesimdi?', 'Varlıklı burjuvazi', ['Sanayi işçileri ve kent yoksulları', 'Eski saray soyluları', 'Topraksız köylüler'], 'Bu döneme \'burjuva monarşisi\' denir; seçme hakkı yüksek vergi ödeyen küçük bir zengin azınlıkla sınırlıydı.'),
  ('Temmuz Monarşisi döneminde oy hakkının genişletilmesini isteyenlere \'Zenginleşin\' diye karşılık verdiği aktarılan başbakan kimdir?', 'François Guizot', ['Adolphe Thiers', 'Alphonse de Lamartine', 'Alexis de Tocqueville'], 'Guizot, seçme hakkının vergiye bağlı kalmasını savundu; çalışıp zenginleşenlerin zaten oy hakkı kazanacağını ileri sürdü. Bu katılık 1848\'e giden yolu açtı.'),
  ('1830 Temmuz Devrimi\'nin ardından aynı yıl Hollanda yönetimine karşı ayaklanarak bağımsızlığını ilan eden ülke hangisidir?', 'Belçika', ['Lüksemburg', 'İsviçre', 'Norveç'], 'Brüksel\'de başlayan ayaklanma, Katolik ve Fransızca konuşan güney eyaletlerinin Protestan Hollanda yönetiminden kopuşunu sağladı.'),
  ('Bağımsız Belçika\'nın ilk kralı olarak 1831\'de tahta çıkan Alman prensi kimdir?', 'I. Leopold', ['I. Otto', 'I. Karol', 'II. Willem'], 'Saxe-Coburg-Gotha hanedanından Leopold, büyük güçlerin onayıyla Belçikalıların kralı oldu; Kraliçe Viktorya\'nın dayısıydı.'),
  ('Şubat 1848 Devrimi\'nin Fransa\'daki doğrudan sonucu hangisidir?', 'Louis-Philippe\'in tahttan çekilmesi ve İkinci Cumhuriyet\'in ilanı', ['Paris Komünü\'nün kurulması', 'X. Charles\'ın tahta dönüp mutlak monarşiyi yeniden kurması', 'III. Napolyon\'un imparator ilan edilmesi'], 'Louis-Philippe İngiltere\'ye kaçtı; geçici hükümet cumhuriyeti ilan etti ve erkekler için genel oy hakkı tanıdı.'),
  ('İkinci Cumhuriyet\'in 1848\'de getirdiği en köklü siyasi değişiklik hangisidir?', 'Erkekler için genel oy hakkı', ['Kadınlar dahil herkese oy hakkı', 'Mutlak monarşi', 'Zümre esaslı meclis'], 'Seçmen sayısı yaklaşık 250 binden 9 milyonun üzerine çıktı; ancak köylü çoğunluk Nisan seçimlerinde ılımlı ve muhafazakâr adaylara oy verdi.'),
  ('1848\'de Paris\'te işsizlere iş sağlamak amacıyla kurulan ve kapatılması Haziran ayaklanmasına yol açan kurum hangisidir?', 'Ulusal Atölyeler', ['Fransa Bankası', 'Ulusal Muhafız\'ın işçi taburları', 'Sanayi Odaları'], 'Louis Blanc\'ın \'çalışma hakkı\' düşüncesinden esinlenen atölyeler pahalı bulundu; Haziran 1848\'de kapatılması işçileri barikatlara döktü.'),
  ('Aralık 1848\'de yapılan ilk genel oylu cumhurbaşkanlığı seçimini büyük farkla kazanan kişi kimdir?', 'Louis-Napoléon Bonaparte', ['Alphonse de Lamartine', 'Louis-Eugène Cavaignac', 'Adolphe Thiers'], 'Napolyon\'un yeğeni oyların yaklaşık dörtte üçünü aldı; adının taşıdığı efsane ve düzen vaadi özellikle köylülerden destek gördü.'),
  ('Louis-Napoléon 1852\'de hangi unvanla imparator ilan edilmiştir?', 'III. Napolyon', ['II. Napolyon', 'I. Louis-Napoléon', 'IV. Napolyon'], 'Bonapartçılar Napolyon\'un oğlu Roma Kralı\'nı II. Napolyon saydıkları için Louis-Napoléon III. Napolyon unvanını aldı.'),
  ('III. Napolyon\'un darbesini protesto edip yaklaşık yirmi yıl sürgünde kalan ve onu \'Küçük Napolyon\' diye alaya alan yazar kimdir?', 'Victor Hugo', ['Gustave Flaubert', 'Émile Zola', 'Alexandre Dumas'], 'Hugo, Manş Denizi\'ndeki Jersey ve Guernsey adalarında yaşadı; \'Sefiller\' romanını da sürgündeyken tamamladı ve 1870\'te Fransa\'ya döndü.'),
  ('III. Napolyon döneminde Paris\'i geniş bulvarlar, parklar ve kanalizasyon sistemiyle yeniden düzenleyen vali kimdir?', 'Baron Haussmann', ['Gustave Eiffel', 'Charles Garnier', 'Le Corbusier'], 'Seine valisi Haussmann 1853-1870 arasında dar Orta Çağ sokaklarını yıkıp düzenli bulvarlar açtı; bugünkü Paris\'in görünümü büyük ölçüde onun eseridir.'),
  ('III. Napolyon döneminde Fransız mühendis Ferdinand de Lesseps\'in önderliğinde açılan ve 1869\'da hizmete giren su yolu hangisidir?', 'Süveyş Kanalı', ['Panama Kanalı', 'Kiel Kanalı', 'Korint Kanalı'], 'Süveyş Kanalı\'nın açılış törenine İmparatoriçe Eugénie katıldı. Lesseps sonradan Panama\'da da kanal girişiminde bulundu ancak başarısız oldu.'),
  ('Mart 1848\'de Viyana\'da çıkan ayaklanmalar sonucunda 1815\'ten beri Avrupa siyasetine yön veren hangi devlet adamı görevini bırakıp kaçmıştır?', 'Metternich', ['Avusturya imparatoru I. Franz Joseph', 'Schwarzenberg', 'Radetzky'], 'Metternich 13 Mart 1848\'de istifa edip İngiltere\'ye kaçtı. Onun düşüşü Viyana sisteminin sarsıldığının simgesi oldu.'),
  ('Mayıs 1848\'de bütün Alman devletlerinden seçilen temsilcilerle toplanan ve birleşik bir Almanya için anayasa hazırlayan meclis hangisidir?', 'Frankfurt Parlamentosu', ['Prusya Landtag\'ı ve Berlin\'deki kraliyet konseyi', 'Reichstag', 'Bundesrat'], 'Frankfurt\'taki Paulskirche\'de toplanan meclis, çoğu avukat, profesör ve memurdan oluştuğu için \'profesörler parlamentosu\' diye de anılır.'),
  ('Frankfurt Parlamentosu\'nun 1849\'da Alman imparatorluk tacını sunduğu, ancak tacı \'çamurdan taç\' diye küçümseyerek reddeden hükümdar kimdir?', 'IV. Friedrich Wilhelm', ['I. Wilhelm', 'III. Friedrich Wilhelm', 'I. Franz Joseph'], 'Prusya kralı, halkın temsilcilerinden gelen bir tacı kabul etmenin ilahi hak anlayışıyla bağdaşmadığını düşündü ve Avusturya ile çatışmaktan da çekindi.'),
  ('1848-1849 Macar devriminin önderi olan ve yenilgiden sonra Osmanlı topraklarına sığınan lider kimdir?', 'Lajos Kossuth', ['Sándor Petőfi', 'Ferenc Deák', 'Gyula Andrássy'], 'Kossuth Nisan 1849\'da Habsburg hanedanının tahttan düştüğünü ilan etti. Devrim yenilince Osmanlı\'ya geçti; sonra İngiltere ve ABD\'ye gitti.'),
  ('1848\'de tahta çıkan ve 1916\'ya kadar yaklaşık 68 yıl hüküm süren Habsburg imparatoru kimdir?', 'I. Franz Joseph', ['I. Ferdinand', 'II. Joseph', 'I. Karl'], 'Genç Franz Joseph, epilepsili amcası I. Ferdinand\'ın tahttan çekilmesiyle 18 yaşında imparator oldu; Avrupa tarihinin en uzun hüküm sürenlerinden biridir.'),
  ('İtalyan ulusal birliğini sağlama sürecine verilen ve \'yeniden diriliş\' anlamına gelen ad hangisidir?', 'Risorgimento', ['Rönesans ve hümanizm dönemi', 'Irredentizm', 'Trasformismo'], 'Risorgimento, 19. yüzyılda İtalyan devletlerinin tek bir ulusal devlet altında birleşmesi sürecini ve bu süreçteki kültürel uyanışı anlatır.'),
  ('1831\'de Marsilya\'da \'Genç İtalya\' örgütünü kuran ve birleşik bir İtalyan cumhuriyeti idealini savunan düşünür kimdir?', 'Giuseppe Mazzini', ['Vittorio Emanuele', 'Camillo Cavour', 'Vincenzo Gioberti'], 'Mazzini halk ayaklanmalarıyla kurulacak birleşik ve cumhuriyetçi bir İtalya\'yı savundu; \'Genç Avrupa\' adlı daha geniş bir örgütün de kurucusudur.'),
  ('1859 savaşında Fransız-Piyemonte ordularının Avusturyalıları yendiği iki büyük meydan savaşı hangileridir?', 'Magenta ve Solferino', ['Custoza ve Novara', 'Sadova ve Sedan', 'Aspromonte ve Mentana'], 'Magenta (Haziran 1859) Milano\'nun yolunu açtı; Solferino ise çok kanlı bir savaştı ve Avusturya\'yı barış istemeye yöneltti.'),
  ('Solferino Savaşı\'ndaki yaralıların durumunu görerek yazdığı kitapla Kızılhaç\'ın kurulmasına öncülük eden İsviçreli kimdir?', 'Henri Dunant', ['Florence Nightingale', 'Gustave Moynier', 'Clara Barton'], 'Dunant\'ın \'Solferino Hatırası\' (1862) kitabı 1863\'te Uluslararası Kızılhaç Komitesi\'nin kurulmasına yol açtı; Dunant 1901\'de ilk Nobel Barış Ödülü\'nü aldı.'),
  ('1860\'ta Piyemonte\'nin orta İtalya düklüklerini ilhak etmesine Fransa\'nın onay vermesinin karşılığı hangisidir?', 'Nice ve Savoie\'nin Fransa\'ya bırakılması', ['Lombardiya\'nın Fransa\'ya verilmesi', 'Sardinya adasının ve Cenova limanının Fransa\'ya verilmesi', 'Roma\'nın Fransa\'ya bırakılması'], 'Torino Antlaşması\'yla Nice ve Savoie Fransa\'ya geçti. Nice doğumlu Garibaldi, memleketinin verilmesine çok kızdı.'),
  ('İtalya Krallığı\'nın resmen ilan edildiği yıl hangisidir?', '1861', ['1859', '1866', '1870'], 'İtalya Krallığı 17 Mart 1861\'de Torino\'da ilan edildi; ancak o sırada Venedik ve Roma henüz krallığın dışındaydı.'),
  ('İtalya Krallığı\'nın ilk başkenti hangi kenttir?', 'Torino', ['Roma', 'Floransa', 'Milano'], 'Başkent 1861\'de Torino, 1865\'te Floransa oldu; Roma\'nın alınmasından sonra 1871\'de Roma\'ya taşındı.'),
  ('Roma\'nın 1870\'te İtalya\'ya katılmasından sonra kendini \'Vatikan tutsağı\' ilan eden papa kimdir?', 'IX. Pius', ['XIII. Leo', 'VII. Pius', 'XI. Pius'], 'IX. Pius İtalya Krallığı\'nı tanımadı ve Vatikan\'dan çıkmadı; papalık ile İtalyan devleti arasındaki \'Roma sorunu\' 1929 Lateran Antlaşmaları\'na kadar sürdü.'),
  ('Birlikten sonra Trento ve Trieste gibi İtalyanca konuşulan ama Avusturya\'da kalan toprakların İtalya\'ya katılmasını savunan akım hangisidir?', 'Irredentizm', ['Federalizm', 'Risorgimento', 'Gallikanizm'], 'Irredentizm \'kurtarılmamış\' (irredenta) topraklar kavramından gelir; bu talep İtalya\'nın 1915\'te Avusturya\'ya karşı savaşa girmesinde etkili oldu.'),
  ('1834\'te Prusya önderliğinde kurulan ve Alman devletleri arasındaki gümrükleri kaldıran birlik hangisidir?', 'Zollverein', ['Bundesrat', 'Hansa Birliği', 'Ren Konfederasyonu'], 'Zollverein Avusturya\'yı dışarıda bıraktı; ekonomik bütünleşme, Prusya\'nın Alman dünyasında siyasi önderliğinin de zeminini hazırladı.'),
  ('1864\'te Prusya ve Avusturya\'nın birlikte Danimarka\'ya karşı savaşmasına yol açan bölgeler hangileridir?', 'Schleswig ve Holstein', ['Alsas ve Loren', 'Bohemya ve Moravya', 'Silezya ve Pomeranya kıyıları'], 'Danimarka\'nın Schleswig\'i kendine bağlama girişimi savaşa yol açtı. Danimarka yenildi ve iki dükalık Prusya ile Avusturya\'nın ortak yönetimine geçti.'),
  ('1866\'da Prusya\'nın Avusturya\'yı kesin olarak yendiği ve Sadova adıyla da bilinen savaş hangisidir?', 'Königgrätz', ['Solferino ve Magenta muharebeleri', 'Sedan', 'Jena'], '3 Temmuz 1866\'daki Königgrätz (Sadova) savaşı yaklaşık yedi hafta süren savaşın sonucunu belirledi.'),
  ('1866 Prusya-Avusturya Savaşı\'nın kısa sürmesi nedeniyle aldığı ad hangisidir?', 'Yedi Hafta Savaşı', ['Altı Gün Savaşı', 'Yüz Gün Savaşı', 'Otuz Gün Savaşı ya da Kısa Savaş'], 'Savaş Haziran ortasından Ağustos başına kadar sürdü; Prusya\'nın demiryolları ve hızlı seferberliği belirleyici oldu.'),
  ('1866\'da Prusya zaferinin mimarı olan ve demiryolları ile telgrafı seferberlikte etkin kullanan genelkurmay başkanı kimdir?', 'Helmuth von Moltke', ['Albrecht von Roon', 'Alfred von Schlieffen', 'Gebhard von Blücher'], 'Yaşlı Moltke, orduları ayrı ayrı yürütüp savaş alanında birleştirme ilkesini demiryolu çağına uyarladı; 1870\'te de Fransa\'yı yendi.'),
  ('1866 savaşından sonra Prusya\'nın ilhak ettiği devletlerden biri aşağıdakilerden hangisidir?', 'Hannover', ['Bavyera', 'Saksonya', 'Württemberg'], 'Prusya; Hannover, Hessen-Kassel, Nassau ve Frankfurt\'u ilhak etti. Saksonya yenilse de varlığını korudu; Bavyera ve Württemberg güney devletleri olarak bağımsız kaldı.'),
  ('1867\'de Prusya önderliğinde Main Irmağı\'nın kuzeyindeki Alman devletlerinden kurulan birlik hangisidir?', 'Kuzey Alman Konfederasyonu', ['Ren Konfederasyonu', 'Alman Konfederasyonu', 'Zollverein'], 'Kuzey Alman Konfederasyonu\'nun anayasası, 1871 Alman İmparatorluğu anayasasının temelini oluşturdu.'),
  ('Bismarck\'ın 1870\'te Ems\'ten gelen telgrafı kısaltarak basına vermesinin amacı neydi?', 'Fransa\'yı kışkırtıp savaşı ilk olarak onun açmasını sağlamak', ['Fransa ile barış imzalamak', 'Kralın tahttan çekildiğini ve oğlunun naip olduğunu duyurmak', 'İspanya\'ya savaş açmak'], 'Kısaltılmış Ems Telgrafı, Fransız elçisi ile Prusya kralı arasındaki görüşmeyi hakaret gibi gösterdi; Fransa 19 Temmuz 1870\'te savaş ilan etti.'),
  ('1-2 Eylül 1870\'te III. Napolyon\'un ordusuyla birlikte esir düştüğü savaş hangisidir?', 'Sedan', ['Metz kuşatması', 'Gravelotte', 'Wörth ve Spicheren'], 'Sedan\'da kuşatılan Fransız ordusu teslim oldu ve imparator esir alındı; bu haber Paris\'te imparatorluğun çöküşünü getirdi.'),
  ('Sedan yenilgisinin haberi üzerine 4 Eylül 1870\'te Paris\'te yaşanan gelişme hangisidir?', 'Üçüncü Cumhuriyet\'in ilan edilmesi', ['III. Napolyon\'un yeniden taç giymesi', 'Paris Komünü\'nün kurulması', 'Bourbonların tahta dönmesi'], 'Paris\'te Ulusal Savunma Hükümeti kuruldu ve cumhuriyet ilan edildi; savaş bu hükümet döneminde sürdü.'),
  ('Prusya kuşatması altındaki Paris\'ten 1870\'te balonla çıkarak taşrada savaşı sürdürmek için ordu toplamaya çalışan Fransız devlet adamı kimdir?', 'Léon Gambetta', ['Adolphe Thiers', 'Jules Ferry', 'Georges Clemenceau'], 'Gambetta Ekim 1870\'te balonla Tours\'a ulaştı ve \'ulusal savunma\' için yeni ordular kurdu, ancak kuşatmayı kaldıramadı.'),
  ('Alman İmparatorluğu 1871\'de ilan edildiğinde ilk imparator olarak tahta çıkan Prusya kralı kimdir?', 'I. Wilhelm', ['II. Wilhelm', 'III. Friedrich', 'IV. Friedrich Wilhelm'], 'I. Wilhelm 18 Ocak 1871\'de Alman imparatoru ilan edildi; Prusya kralı unvanını da korudu.'),
  ('1871 Alman İmparatorluğu\'nda erkeklerin genel oyuyla seçilen meclis hangisidir?', 'Reichstag', ['Bundesrat', 'Landtag', 'Herrenhaus'], 'Reichstag genel oyla seçilirdi ama hükümeti denetleme yetkisi sınırlıydı; şansölye meclise değil imparatora karşı sorumluydu.'),
  ('1871\'de Paris Komünü\'nü bastıran hükümetin başı kimdir?', 'Adolphe Thiers', ['Léon Gambetta', 'Jules Ferry', 'Patrice de Mac-Mahon'], 'Thiers yönetimindeki Versay hükümeti Mayıs 1871\'de orduyu Paris\'e gönderdi; Thiers ardından cumhuriyetin ilk cumhurbaşkanı oldu.'),
  ('Mayıs 1871\'de Versay ordusunun Paris\'e girip binlerce komüncüyü öldürdüğü haftaya ne ad verilir?', 'Kanlı Hafta', ['Haziran Günleri', 'Büyük Korku', 'Üç Şanlı Gün'], '21-28 Mayıs 1871 arasındaki \'Semaine sanglante\'de çatışmalar ve toplu infazlarda on binlerce kişinin öldüğü tahmin edilir.'),
  ('1880\'de Fransa\'da ulusal bayram olarak kabul edilen gün hangisidir?', '14 Temmuz', ['4 Ağustos', '2 Aralık', '21 Ocak'], 'Üçüncü Cumhuriyet, devrim mirasını sahiplenmek için 14 Temmuz\'u ulusal bayram yaptı; tarih hem Bastille\'in alınmasını hem 1790 Federasyon Bayramı\'nı anar.'),
  ('1880\'lerin başında Fransa\'da ilköğretimi parasız, zorunlu ve laik yapan yasaların mimarı olan bakan kimdir?', 'Jules Ferry', ['Adolphe Thiers', 'Léon Gambetta', 'Jean Jaurès'], 'Ferry yasaları (1881-1882) cumhuriyetçi değerleri yaymayı ve Kilise\'nin eğitim üzerindeki etkisini azaltmayı amaçladı.'),
  ('1880\'lerin sonunda popülerliğiyle cumhuriyeti darbe tehdidi altına sokan ama sonunda Belçika\'ya kaçan Fransız general kimdir?', 'Georges Boulanger', ['Patrice de Mac-Mahon', 'Louis-Eugène Cavaignac', 'Joseph Joffre'], '\'General Revanş\' diye anılan Boulanger, 1889\'da darbe beklentisi yaratmasına karşın harekete geçmedi; 1891\'de Brüksel\'de intihar etti.'),
  ('1894\'te Almanya\'ya casusluk yaptığı iddiasıyla haksız yere mahkûm edilen Yahudi Fransız subay kimdir?', 'Alfred Dreyfus', ['Ferdinand Esterhazy', 'Georges Picquart', 'Hubert-Joseph Henry'], 'Yüzbaşı Dreyfus, Şeytan Adası\'na sürgüne gönderildi. Gerçek casusun Esterhazy olduğu sonradan ortaya çıktı; Dreyfus 1906\'da tamamen aklandı.'),
  ('Paris\'te 1889 Dünya Sergisi için inşa edilen Eyfel Kulesi hangi olayın yüzüncü yılına denk getirilmiştir?', 'Fransız Devrimi', ['Napolyon\'un doğumu', 'Waterloo Savaşı', 'Viyana Kongresi'], '1889 sergisi devrimin yüzüncü yılını kutluyordu; kule başta pek çok sanatçının tepkisini çekse de kentin simgesi oldu.'),
  ('Bismarck\'ın 1870\'lerde Katolik Kilisesi\'nin Almanya\'daki etkisini kısmak için yürüttüğü mücadeleye ne ad verilir?', 'Kulturkampf', ['Realpolitik', 'Weltpolitik', 'Gleichschaltung'], 'Kulturkampf \'kültür mücadelesi\' demektir. Okulların denetimi, din adamlarının atanması ve sivil nikâh gibi alanlarda yasalar çıkarıldı.'),
  ('1871 sonrasında Bismarck\'ın dış politikasının temel hedefi neydi?', 'Fransa\'yı yalnız bırakıp yeni bir savaşı önlemek', ['Fransa\'yı yeniden işgal edip bölmek', 'Rusya\'ya savaş açmak', 'Avusturya\'yı savaşla Almanya\'ya katıp Viyana\'yı başkent yapmak'], 'Bismarck Almanya\'yı \'doymuş\' bir güç olarak gördü; Fransa\'nın intikam için müttefik bulmasını engelleyen ittifaklar kurdu.'),
  ('1873\'te Almanya, Avusturya-Macaristan ve Rusya imparatorları arasında kurulan uzlaşmaya ne ad verilir?', 'Üç İmparator Ligi', ['Kutsal İttifak', 'Üçlü İttifak', 'Dörtlü İttifak'], 'Dreikaiserbund, muhafazakâr monarşilerin dayanışmasına dayanıyordu; ancak Balkanlar\'daki Avusturya-Rusya rekabeti onu zayıflattı.'),
  ('Almanya ile Avusturya-Macaristan arasında 1879\'da imzalanan ve Rusya\'ya karşı karşılıklı yardımı öngören savunma antlaşması hangisidir?', 'İkili İttifak', ['Üçlü İtilaf', 'Reasürans Antlaşması', 'Akdeniz Antlaşmaları'], 'İkili İttifak 1918\'e kadar sürdü ve Birinci Dünya Savaşı\'ndaki Merkezî Devletler bloğunun çekirdeğini oluşturdu.'),
  ('1882\'de Almanya ve Avusturya-Macaristan\'ın kurduğu ittifaka katılan üçüncü devlet hangisidir?', 'İtalya', ['Osmanlı Devleti', 'Romanya', 'İspanya'], 'İtalya, Fransa\'nın 1881\'de Tunus\'u almasına tepki olarak Üçlü İttifak\'a katıldı.'),
  ('Bismarck hangi imparator tarafından 1890\'da görevden alınmıştır?', 'II. Wilhelm', ['I. Wilhelm', 'III. Friedrich', 'I. Franz Joseph'], 'Genç imparator kendi politikasını yürütmek istiyordu; sosyalistlere ve Rusya\'ya karşı tutum konusundaki anlaşmazlıklar Bismarck\'ın istifasıyla sonuçlandı.'),
  ('İngiliz Punch dergisinin 1890\'da yayımladığı \'Kılavuz kaptan gemiden iniyor\' (Dropping the Pilot) karikatürü hangi olayı konu alır?', 'Bismarck\'ın görevden ayrılması', ['III. Napolyon\'un esir düşmesi', 'Metternich\'in 1848\'de Viyana\'dan kaçışı', 'Cavour\'un ölümü'], 'Karikatürde gemiden inen kılavuz kaptan Bismarck, güverteden onu izleyen kişi ise II. Wilhelm\'dir.'),
  ('II. Wilhelm\'in Bismarck sonrası izlediği, Almanya\'yı küresel bir sömürge ve deniz gücü yapmayı hedefleyen politikaya ne ad verilir?', 'Weltpolitik', ['Realpolitik', 'Kulturkampf', 'Ostpolitik'], 'Weltpolitik (\'dünya politikası\') büyük bir donanma kurulmasını öngördü ve İngiltere ile deniz silahlanma yarışına yol açtı.'),
  ('Bismarck\'ın siyasette ideolojiden çok çıkarlara ve güç ilişkilerine dayanan pratik yaklaşımını anlatmak için kullanılan kavram hangisidir?', 'Realpolitik', ['Weltpolitik', 'Lebensraum', 'Panslavizm'], 'Realpolitik kavramını ilk kez Ludwig von Rochau ortaya attı; Bismarck\'ın gerektiğinde liberallerle, gerektiğinde muhafazakârlarla ittifak yapması bu yaklaşımın örneğidir.'),
  ('Avusturya\'nın 1866 yenilgisinden sonra Macarlarla 1867\'de vardığı ve devleti iki eşit parçaya bölen düzenlemeye ne ad verilir?', 'Uzlaşma (Ausgleich)', ['Pragmatik Yaptırım (Sanctio Pragmatica)', 'Olmütz Uzlaşması', 'Ekim Diploması'], 'Ausgleich ile Avusturya İmparatorluğu Avusturya-Macaristan\'a dönüştü; Macaristan kendi parlamentosuna ve hükümetine kavuştu.'),
  ('Çar I. Nikola\'nın 1848 devrimlerini bastırmadaki rolü nedeniyle aldığı lakap hangisidir?', 'Avrupa\'nın jandarması', ['Kurtarıcı çar', 'Avrupa\'nın hasta adamı', 'Dürüst simsar'], 'I. Nikola hem kendi ülkesinde hem de Macar devrimine müdahaleyle Avrupa\'da devrimlere karşı düzenin bekçisi rolünü üstlendi.'),
  ('Rusya\'da serfliği 1861\'de kaldıran çar kimdir?', 'II. Aleksandr', ['I. Nikola', 'III. Aleksandr', 'II. Nikola'], 'II. Aleksandr Kırım yenilgisinden sonra reformlara girişti; 1861 fermanıyla yirmi milyonu aşkın serf özgürlüğüne kavuştu.'),
  ('II. Aleksandr döneminde 1864\'te kurulan seçilmiş yerel yönetim meclislerine ne ad verilir?', 'Zemstvo', ['Duma', 'Sovyet', 'Mir'], 'Zemstvolar okul, sağlık ve yol gibi yerel işleri yürüttü; liberal aydınların kamu hizmetinde deneyim kazandığı kurumlar oldu.'),
  ('III. Aleksandr döneminde Rus İmparatorluğu\'ndaki Polonyalı, Baltık ve diğer halklara Rus dili ve Ortodoksluğu dayatılmasına ne ad verilir?', 'Ruslaştırma', ['Batılılaşma', 'Slavofillik', 'Federalleşme'], 'Ruslaştırma politikası okullarda ve yönetimde Rusçayı zorunlu tuttu; Yahudilere yönelik kısıtlamalar ve pogromlar da bu dönemde arttı.'),
  ('Bütün Slav halklarının Rusya önderliğinde birleşmesini ya da dayanışmasını savunan 19. yüzyıl akımı hangisidir?', 'Panslavizm', ['Pancermenizm', 'Siyonizm', 'Filhelenizm'], 'Panslavizm, özellikle Balkan Slavlarının Osmanlı ve Habsburg yönetiminden kurtulmasını savunarak Rusya\'nın Balkan politikasını etkiledi.'),
  ('19. yüzyıl Rus düşüncesinde Rusya\'nın Batı\'yı taklit etmek yerine Ortodoksluk ve köy topluluğuna dayalı kendi yolunu izlemesi gerektiğini savunanlara ne ad verilir?', 'Slavofiller', ['Batıcılar', 'Narodnikler', 'Dekabristler'], 'Slavofiller ile Batıcılar arasındaki tartışma, Rusya\'nın Avrupa\'nın bir parçası mı yoksa ayrı bir uygarlık mı olduğu sorusu etrafında dönüyordu.'),
  ('1819\'da Manchester\'da parlamento reformu isteyen kalabalığa süvarilerin saldırmasıyla yaşanan ve adı Waterloo\'ya gönderme yapan olay hangisidir?', 'Peterloo Katliamı', ['Kanlı Pazar', 'Champ de Mars Katliamı', 'Tolpuddle Olayı'], 'St Peter\'s Field\'daki saldırıda en az on beş kişi öldü; olay alaycı biçimde \'Peterloo\' diye adlandırıldı.'),
  ('İngiltere\'de 1838\'de yayımlanan Halk Şartı\'na dayanarak genel erkek oy hakkı ve gizli oy gibi talepler için mücadele eden işçi hareketi hangisidir?', 'Çartizm', ['Ludizm', 'Fabianizm', 'Owenizm'], 'Halk Şartı\'nın altı maddesi arasında genel erkek oy hakkı, gizli oy, milletvekillerine maaş ve yıllık seçimler vardı. Çartistlerin dilekçeleri parlamentoca reddedildi.'),
  ('Çartistlerin Halk Şartı\'nda yer alan taleplerden biri aşağıdakilerden hangisidir?', 'Gizli oy', ['Kraliyetin kaldırılması', 'Lordlar Kamarası\'nın genişletilmesi', 'Kadınlara askerlik yükümlülüğü'], 'Gizli oy 1872 Ballot Act ile gerçekleşti; Çartistlerin yıllık seçim dışındaki talepleri zamanla büyük ölçüde kabul edildi.'),
  ('Tahıl Yasaları\'nı 1846\'da kaldırarak kendi Muhafazakâr Partisi\'ni bölen başbakan kimdir?', 'Robert Peel', ['Benjamin Disraeli', 'William Gladstone', 'Lord Melbourne'], 'Peel, İrlanda kıtlığı karşısında tahılın ucuzlaması gerektiğini savunarak yasayı kaldırdı; parti korumacılar ve Peel yanlıları olarak ikiye bölündü.'),
  ('1845-1849 yılları arasında patates hastalığı nedeniyle yaklaşık bir milyon kişinin öldüğü ve bir milyondan fazlasının göç ettiği kıtlık hangi ülkede yaşanmıştır?', 'İrlanda', ['İskoçya', 'Galler', 'Hollanda'], 'Büyük Kıtlık İrlanda nüfusunu kalıcı biçimde azalttı ve İngiltere\'ye karşı İrlanda ulusçuluğunu derinleştirdi.'),
  ('1851\'de Londra\'da düzenlenen ve demir ile camdan yapılmış Kristal Saray\'da açılan sergi hangi adla bilinir?', 'Büyük Sergi', ['Dünya Ticaret Fuarı', 'Viktorya Panayırı', 'Kraliyet Sanayi Gösterisi'], 'Prens Albert\'in desteklediği Great Exhibition, İngiltere\'nin sanayi üstünlüğünü dünyaya sergiledi; on binden fazla katılımcı ürünlerini gösterdi.'),
  ('İngiltere\'de 1867\'de ikinci Reform Yasası\'nı geçirerek kentli işçilerin önemli bir bölümüne oy hakkı tanıyan Muhafazakâr devlet adamı kimdir?', 'Benjamin Disraeli', ['William Ewart Gladstone', 'Robert Peel', 'Lord Palmerston'], 'Disraeli, Liberallerin önünü keserek reformu kendi partisi adına gerçekleştirdi; bu hamle \'karanlıkta sıçrayış\' diye nitelendi.'),
  ('19. yüzyılın ikinci yarısında İngiliz siyasetinde Disraeli\'nin büyük rakibi olan ve dört kez başbakanlık yapan Liberal lider kimdir?', 'William Gladstone', ['Lord Salisbury', 'Joseph Chamberlain', 'Lord Palmerston'], 'Gladstone İrlanda\'ya özerklik (Home Rule) vermeye çalıştı; 1886 ve 1893\'teki tasarıları başarısız oldu.'),
  ('Kraliçe Viktorya\'ya 1876\'da Disraeli hükümeti tarafından verilen yeni unvan hangisidir?', 'Hindistan İmparatoriçesi', ['Kanada Kraliçesi', 'Avustralya İmparatoriçesi', 'Mısır Hükümdarı'], 'Royal Titles Act ile Viktorya Hindistan İmparatoriçesi oldu; bu unvan imparatorluğun prestijini simgeliyordu.'),
  ('1790\'da yayımladığı \'Fransa\'daki Devrim Üzerine Düşünceler\' adlı eseriyle modern muhafazakârlığın kurucusu sayılan İrlanda kökenli İngiliz düşünür kimdir?', 'Edmund Burke', ['Thomas Paine', 'John Locke', 'Jeremy Bentham'], 'Burke, toplumu kuşaklar arası bir sözleşme olarak gördü; soyut ilkelere dayanarak geleneği yıkmanın kaosa ve tiranlığa yol açacağını öngördü.'),
  ('\'Özgürlük Üzerine\' (1859) adlı eserinde bireyin, başkalarına zarar vermedikçe davranışlarında özgür olması gerektiğini savunan İngiliz düşünür kimdir?', 'John Stuart Mill', ['Herbert Spencer', 'Adam Smith', 'Thomas Carlyle'], 'Mill \'zarar ilkesi\'ni ortaya koydu; ayrıca kadınlara oy hakkı için parlamentoda öneri veren ilk milletvekillerinden biri oldu.'),
  ('Ütopyacı sosyalistlerden olup İskoçya\'daki New Lanark fabrikasında işçilere iyi konut ve okullar sağlayan, sonra ABD\'de New Harmony topluluğunu kuran sanayici kimdir?', 'Robert Owen', ['Charles Fourier', 'Henri de Saint-Simon', 'Étienne Cabet'], 'Owen, insan karakterinin çevre tarafından biçimlendiğine inanıyordu; kooperatif hareketinin öncülerinden biri sayılır.'),
  ('Birinci Enternasyonal\'de Marx ile çatışan ve devletin derhâl yıkılmasını savunan Rus anarşist kimdir?', 'Mihail Bakunin', ['Lev Tolstoy', 'Georgi Plehanov', 'Aleksandr Herzen'], 'Marx proletaryanın devleti ele geçirmesini öngörürken Bakunin her türlü devleti reddediyordu; 1872\'de Bakunin ve yandaşları Enternasyonal\'den çıkarıldı.'),
  ('1889\'da Paris\'te kurulan İkinci Enternasyonal\'in işçi hareketine bıraktığı kalıcı geleneklerden biri hangisidir?', '1 Mayıs\'ın işçi bayramı olarak kutlanması', ['Kızılhaç örgütünün kurulması', 'Kızıl bayrağın yasaklanması', 'Grevlerin yasaklanması'], 'İkinci Enternasyonal, sekiz saatlik iş günü talebi ve 1886 Chicago olaylarının anısına 1 Mayıs\'ı uluslararası eylem günü ilan etti.'),
  ('Karl Marx\'ın kapitalist üretim biçimini çözümlediği ve ilk cildi 1867\'de yayımlanan eseri hangisidir?', 'Das Kapital', ['Komünist Manifesto', 'Ailenin Kökeni', 'Felsefenin Sefaleti'], 'Das Kapital\'in ilk cildi Marx\'ın sağlığında yayımlandı; ikinci ve üçüncü ciltleri Engels Marx\'ın notlarından derleyerek yayımladı.'),
  ('1875\'te iki işçi partisinin birleşmesiyle kurulan ve 1890\'larda Almanya\'nın en çok oy alan partisine dönüşen parti hangisidir?', 'Sosyal Demokrat Parti (SPD)', ['Merkez Partisi', 'Ulusal Liberal Parti (Nationalliberale)', 'Muhafazakâr Parti'], 'Gotha\'da birleşen sosyalistler, Anti-Sosyalist Yasa\'ya karşın güçlendi; 1912 seçimlerinde Reichstag\'ın en büyük partisi oldu.'),
  ('Her halkın kendine özgü bir \'halk ruhu\' (Volksgeist) olduğunu ve bunun dilde ve halk şarkılarında yaşadığını savunan 18. yüzyıl Alman düşünürü kimdir?', 'Johann Gottfried Herder', ['Immanuel Kant', 'Friedrich Schiller', 'Gottfried Leibniz'], 'Herder\'in dil ve kültüre dayalı ulus anlayışı, 19. yüzyılda özellikle Orta ve Doğu Avrupa\'daki kültürel ulusçulukları derinden etkiledi.'),
  ('Fransız işgali altındaki Berlin\'de 1807-1808\'de verdiği \'Alman Ulusuna Söylevler\' ile Alman ulusal bilincini uyandırmaya çalışan filozof kimdir?', 'Johann Gottlieb Fichte', ['Georg Wilhelm Friedrich Hegel', 'Friedrich Schelling', 'Arthur Schopenhauer'], 'Fichte, Almanların ortak dil ve kültür temelinde bir ulus olduğunu ve eğitim yoluyla ulusal yenilenme gerektiğini vurguladı.'),
  ('19. yüzyılda ulusçuluğun etkisi açısından aşağıdaki karşılaştırmalardan hangisi doğrudur?', 'İtalya ve Almanya\'da birleştirici, çok uluslu imparatorluklarda ise bölücü bir güç oldu', ['Her yerde imparatorlukları güçlendirdi', 'Yalnız İngiltere\'yi etkiledi', 'İtalya ve Almanya\'yı daha da böldü'], 'Dağınık devletlerden oluşan İtalya ve Almanya\'da ulusçuluk birleşmeyi sağladı; Habsburg, Osmanlı ve Rus imparatorluklarında ise ayrılıkçı hareketleri güçlendirdi.'),
  ('Victor Hugo\'nun 1832 Haziran ayaklanmasını da konu alan ve Paris barikatlarını ölümsüzleştiren romanı hangisidir?', 'Sefiller', ['Notre-Dame\'ın Kamburu', 'Kırmızı ve Siyah', 'Germinal'], 'Sefiller (1862), Restorasyon ve Temmuz Monarşisi Fransa\'sındaki yoksulluğu ve 1832 cumhuriyetçi ayaklanmasını anlatır; çoğu kez yanlışlıkla 1789 ile karıştırılır.'),
  ('Norveç, İsveç ile olan birliğinden hangi yıl barışçıl biçimde ayrılarak tam bağımsızlığını kazanmıştır?', '1905', ['1814', '1848', '1918'], 'Norveç meclisinin kararı ve ardından yapılan halkoylamasıyla birlik sona erdi; Danimarkalı Prens Carl, VII. Haakon adıyla Norveç kralı oldu.'),
  ('Fransız Devrimi\'nin ilk yıllarında 1790\'da Paris\'te Champ de Mars\'ta düzenlenen ve ulusal birliği kutlayan büyük şenlik hangisidir?', 'Federasyon Bayramı', ['Yüce Varlık Bayramı', 'Akıl Bayramı', 'Zafer Şenliği'], '14 Temmuz 1790\'daki Fête de la Fédération\'da kral anayasaya bağlılık yemini etti; Bastille\'in yıl dönümü olan bu tarih bugünkü ulusal bayramın da kaynağıdır.'),
  ('1789 İnsan ve Yurttaş Hakları Bildirisi\'nde \'dokunulmaz ve kutsal\' olarak nitelenen hak hangisidir?', 'Mülkiyet', ['Çalışma', 'Eğitim', 'Sağlık'], 'Bildirinin son maddesi (17. madde) mülkiyeti dokunulmaz ve kutsal bir hak olarak tanımlar; bu vurgu devrimin burjuva niteliğini gösterir.'),
  ('Kraliyet koleksiyonlarının halka açılmasıyla 1793\'te kurulan müze hangisidir?', 'Louvre Müzesi', ['Orsay Müzesi', 'Versay Müzesi', 'Cluny Müzesi'], 'Louvre Sarayı\'ndaki koleksiyon Ağustos 1793\'te \'Cumhuriyetin Merkez Sanat Müzesi\' olarak açıldı; sanatın ulusa ait olduğu düşüncesini simgeler.'),
  ('Devrim döneminde bir kiliseden dönüştürülerek \'büyük adamlar\'ın gömüldüğü bir anıt mezar hâline getirilen Paris yapısı hangisidir?', 'Panthéon', ['Les Invalides', 'Sainte-Chapelle', 'Madeleine'], 'Sainte-Geneviève Kilisesi 1791\'de Panthéon\'a dönüştürüldü; Voltaire ve Rousseau\'nun naaşları buraya taşındı.'),
  ('Modern kimyanın kurucularından sayılan, ancak eski vergi tahsildarlığı görevi yüzünden 1794\'te giyotinle idam edilen bilim insanı kimdir?', 'Antoine Lavoisier', ['Pierre-Simon Laplace', 'Joseph-Louis Lagrange', 'Gaspard Monge'], 'Lavoisier, Eski Rejim\'in vergi toplayan şirketi Ferme générale\'in ortağıydı. Lagrange\'ın \'Bu kafayı kesmek bir an sürdü, benzerini yetiştirmek yüz yıl sürmeyebilir\' dediği aktarılır.'),
  ('İtalyan ve Alman birliklerinde Piyemonte ile Prusya\'nın üstlendiği rol bakımından ortak özellik hangisidir?', 'Her ikisinin de birliğe önderlik eden çekirdek devlet olması', ['Her ikisinin de Avusturya\'nın en sadık müttefiki olması', 'Her ikisinin de cumhuriyet olması', 'Her ikisinin de birliğe karşı çıkması'], 'Piyemonte-Sardinya ve Prusya, ordu, diplomasi ve monarşi kurumlarıyla dağınık devletleri kendi çevrelerinde birleştirdi.'),
  ('Aşağıdaki olaylardan hangisi kronolojik olarak en sondadır?', 'Paris Komünü', ['Solferino Savaşı', 'Königgrätz Savaşı', 'Frankfurt Parlamentosu\'nun toplanması'], 'Frankfurt Parlamentosu 1848, Solferino 1859, Königgrätz 1866, Paris Komünü 1871 tarihlidir.'),
  ('Alman birliğine giden üç savaşın doğru sırası hangisidir?', 'Danimarka (1864), Avusturya (1866), Fransa', ['Avusturya, Danimarka, Fransa', 'Fransa, Avusturya, Danimarka', 'Danimarka, Fransa, Avusturya'], 'Bismarck önce Avusturya ile birlikte Danimarka\'yı, sonra Avusturya\'yı, en son da Fransa\'yı yendi.'),
  ('XVI. Louis\'nin idamı ile Napolyon\'un imparator ilan edilmesi arasında kaç yıl vardır?', '11', ['8', '13', '15'], 'XVI. Louis Ocak 1793\'te idam edildi, Napolyon 1804\'te imparator ilan edildi: 1804 - 1793 = 11 yıl.'),
  ('Trafalgar Deniz Savaşı\'nda (1805) İngiliz filosunu zafere götüren ancak savaş sırasında vurularak ölen amiral kimdir?', 'Horatio Nelson', ['Cuthbert Collingwood', 'Edward Pellew', 'George Rodney'], 'Nelson, Fransız-İspanyol filosunu yendiği savaşta keskin nişancı tarafından vuruldu; Londra\'daki Trafalgar Meydanı\'ndaki sütun onun anısına dikildi.'),
  ('Kraliçe Viktorya hangi yıl İngiliz tahtına çıkmıştır?', '1837', ['1815', '1848', '1851'], 'Viktorya 1837\'de 18 yaşında tahta çıktı ve 1901\'e kadar hüküm sürdü; bu uzun dönem \'Viktorya Çağı\' olarak anılır.'),
  ('III. Napolyon esir düştükten sonra imparatorluk ailesinin sığındığı ve III. Napolyon\'un 1873\'te öldüğü ülke hangisidir?', 'İngiltere', ['Belçika', 'İsviçre', 'İtalya'], 'III. Napolyon esaretten serbest bırakılınca İngiltere\'ye geçti ve Chislehurst\'te yaşadı; oğlu imparatorluk prensi 1879\'da Zulu Savaşı\'nda öldü.'),
  ('Bir konuşmacı şöyle diyor: \'Toplum, ölmüşler, yaşayanlar ve doğacaklar arasında bir ortaklıktır; atalarımızın bilgeliğini bir günde yıkamayız.\' Bu görüş hangi ideolojiye en yakındır?', 'Muhafazakârlık', ['Anarşizm', 'Jakobenizm', 'Ütopyacı sosyalizm ve ortak yaşam toplulukları'], 'Kuşaklar arası sözleşme ve geleneğe saygı vurgusu Burke\'ün muhafazakârlığının özüdür.'),
  ('Bir broşürde \'Hükümet en az yöneten hükümettir; devletin görevi bireyin canını, mülkünü ve sözleşmelerini korumaktır\' deniyor. Bu görüş 19. yüzyılın hangi akımını yansıtır?', 'Klasik liberalizm', ['Muhafazakâr mutlakiyetçilik', 'Devrimci sosyalizm', 'Panslavizm ve Ortodoks birliği'], 'Sınırlı devlet, bireysel haklar ve mülkiyetin korunması klasik liberalizmin temel ilkeleridir.'),
  ('Bir öğrenci şu olayları birbirine bağlıyor: Kötü hasat, ekmek fiyatlarının artması, devletin iflasın eşiğine gelmesi. Bu olaylar zinciri en doğrudan hangi gelişmeyi açıklar?', '1789\'da Etats Généraux\'nun toplanmasını', ['1830\'da Belçika\'nın bağımsızlığını', '1871\'de Alman birliğinin kurulmasını', '1815\'te Viyana Kongresi\'nin toplanmasını'], 'Mali iflas ve toplumsal hoşnutsuzluk, kralı 175 yıldır toplanmayan Etats Généraux\'yu çağırmak zorunda bıraktı.'),
  ('Bir tarih belgesinde \'Kral, bundan böyle yalnızca yasa adına hüküm sürer; yasaları ulusun temsilcileri yapar\' ifadesi bulunuyor. Bu belge en çok hangi rejimin ilkesini yansıtır?', 'Anayasal monarşi', ['Mutlak monarşi', 'Askerî diktatörlük ve sıkıyönetim', 'Teokrasi'], 'Kralın yasa ile sınırlandığı ve yasama yetkisinin temsilcilere ait olduğu düzen anayasal monarşidir; 1791 Fransız Anayasası bunun örneğidir.'),
  ('1830\'da Paris\'teki devrimin hemen ardından Brüksel ve Varşova\'da da ayaklanmalar çıkmıştır. Bu durum aşağıdakilerden hangisini en iyi gösterir?', 'Devrimci düşüncelerin Avrupa\'da hızla yayılabildiğini', ['Avrupa\'da hiçbir haberleşme olmadığını', 'Bu ülkelerin Fransa\'ya bağlı olduğunu', 'Ayaklanmaların Fransız ordusunca örgütlenip başlatıldığını'], 'Paris\'teki başarı, liberal ve ulusçu grupları cesaretlendirdi; 1830 ve 1848 dalgaları Avrupa\'nın birbirine bağlı siyasi iklimini gösterir.'),
  ('Bir çizimde Garibaldi, kırmızı gömlekli gönüllülerin önünde ilerlerken gösteriliyor; arka planda Sicilya kıyıları var. Bu çizim hangi yıla ait bir olayı canlandırmaktadır?', '1860', ['1848', '1866', '1870'], 'Garibaldi\'nin Bin Kişilik gönüllü birliği Mayıs 1860\'ta Sicilya\'ya çıktı.'),
  ('Bir Alsaslı 1872\'de Fransız ya da Alman yurttaşlığı arasında seçim yapmak zorunda kalıyor. Bu durumun nedeni hangi antlaşmadır?', 'Frankfurt Antlaşması', ['Viyana Kongresi Son Senedi', 'Prag Barışı', 'Campo Formio Antlaşması'], '1871 Frankfurt Antlaşması Alsas ve Loren\'in bir bölümünü Almanya\'ya bıraktı; bölge halkına belirli bir süre içinde Fransız yurttaşlığını seçip göç etme hakkı tanındı.'),
  ('1871 sonrası Fransız okul haritalarında Alsas-Loren\'in farklı bir renkle boyanması ve \'kayıp eyaletler\' diye anılması hangi duyguyu beslemeyi amaçlıyordu?', 'İntikam ve toprakları geri alma isteğini', ['Almanya ile kalıcı dostluk ve ekonomik iş birliği isteğini', 'Sömürgelerden vazgeçmeyi', 'Monarşinin geri gelmesini'], 'Üçüncü Cumhuriyet okulları kayıp eyaletleri sürekli hatırlatarak ulusal bilinç ve revanş duygusu aşıladı.'),
  ('Bir işçi 1883\'te Almanya\'da hastalandığında belirli bir süre gelir desteği alabiliyor. Bu destek hangi politikanın ürünüdür?', 'Bismarck\'ın sosyal sigorta yasalarının', ['Weltpolitik\'in ve donanma programının', 'Kulturkampf\'ın', 'Zollverein\'in'], '1883 hastalık sigortası, Bismarck\'ın işçileri sosyalizmden uzaklaştırmak için başlattığı sosyal güvenlik programının ilk adımıdır.'),
  ('Bir öğrenci 1815 sonrası Avrupa\'da üç büyük akımı şu sloganlarla eşleştiriyor: \'Taht ve sunak\', \'Anayasa ve özgürlük\', \'Bir dil, bir ulus, bir devlet\'. Bu eşleştirme sırasıyla hangi akımları gösterir?', 'Muhafazakârlık, liberalizm, ulusçuluk', ['Liberalizm, sosyalizm, anarşizm', 'Ulusçuluk, muhafazakârlık, sosyalizm', 'Sosyalizm, ulusçuluk, liberalizm'], 'Taht ve sunak monarşi ile Kilise ittifakını, anayasa ve özgürlük liberalleri, dil-ulus-devlet birliği ise ulusçuları temsil eder.'),
  ('Bir anı kitabında \'Neman\'ı geçtiğimizde yüz binlerdik; geri döndüğümüzde bir avuç kalmıştık\' yazıyor. Yazar hangi seferi anlatıyor?', '1812 Rusya seferi', ['1798 Mısır seferi', '1796 İtalya seferi', '1808 İspanya seferi'], 'Büyük Ordu Haziran 1812\'de Neman\'ı geçerek Rusya\'ya girdi ve Aralık\'ta perişan hâlde geri döndü.'),
  ('Napolyon\'un \'Bütün Fransız askerleri sırt çantalarında bir mareşal asası taşır\' sözü hangi ilkeyi anlatır?', 'Yeteneği olan herkesin en yüksek rütbeye çıkabileceğini', ['Askerlerin ve subayların yalnızca soylu ailelerden seçildiğini', 'Ordunun yalnız gönüllülerden oluştuğunu', 'Rütbelerin satın alınabileceğini'], 'Söz, doğuma değil başarıya dayalı yükselme (liyakat) ilkesini vurgular; Napolyon\'un mareşallerinin çoğu sıradan ailelerden geliyordu.'),
  ('Metternich\'in \'İtalya yalnızca bir coğrafi deyimdir\' sözü hangi görüşü dile getirir?', 'İtalya\'nın siyasi bir ulus olarak var olmadığını', ['İtalya\'nın en güçlü Avrupa devleti olduğunu', 'İtalya\'nın Avusturya\'dan bağımsız olması gerektiğini', 'İtalya\'nın Fransa\'ya ait olduğunu'], 'Metternich, İtalyan yarımadasının ayrı devletlerden oluştuğunu ve ortak bir siyasi kimliği bulunmadığını vurgulayarak İtalyan ulusçuluğunu küçümsedi.'),
  ('\'Özgürlük, Eşitlik, Kardeşlik\' sloganı hangi olayla özdeşleşmiş ve bugün de bir ülkenin resmî düsturudur?', 'Fransız Devrimi', ['İngiliz Şanlı Devrimi ve Haklar Bildirgesi', 'Rus Devrimi', 'Amerikan İç Savaşı'], 'Slogan Fransız Devrimi döneminde yaygınlaştı ve Fransız Cumhuriyeti\'nin resmî düsturu oldu.'),
  ('Fransız Devrimi\'nin Avrupa\'ya yaydığı fikirlerden biri aşağıdakilerden hangisi değildir?', 'Kralların yetkisinin doğrudan Tanrı\'dan geldiği', ['Ulusal egemenlik', 'Bireysel hak ve özgürlükler', 'Yasa önünde eşitlik ve ayrıcalıkların kaldırılması'], 'İlahi hak öğretisi Eski Rejim\'in dayanağıydı; devrim bunun yerine egemenliğin ulusta olduğu ilkesini yaydı.'),
  ('Bir köylü 1790\'da artık senyörün değirmenini kullanmak zorunda olmadığını ve Kilise\'ye öşür vermediğini anlatıyor. Bu değişiklik hangi kararın sonucudur?', '4 Ağustos 1789 kararlarının', ['Napolyon Kanunu\'nun (Code civil) aile hükümlerinin', 'Karlsbad Kararları\'nın', 'Viyana Kongresi\'nin'], '4 Ağustos gecesi alınan kararlarla feodal ayrıcalıklar ve öşür kaldırıldı; senyörlük tekelleri sona erdi.'),
  ('Aşağıdaki kişi-olay eşleştirmelerinden hangisi doğrudur?', 'Kossuth - 1848 Macar devrimi', ['Metternich - Paris Komünü', 'Thiers - Frankfurt Parlamentosu', 'Robespierre - Viyana Kongresi'], 'Kossuth 1848-1849 Macar devriminin önderidir. Metternich Viyana düzeninin, Thiers Komün\'ü bastıran hükümetin, Robespierre ise Terör döneminin figürüdür.'),
  ('19. yüzyıl ulus devletlerinin kuruluşunda savaşların payını göz önüne aldığınızda, aşağıdaki yargılardan hangisi en savunulabilirdir?', 'İtalyan ve Alman birlikleri büyük ölçüde savaşlarla tamamlanmıştır', ['Hiçbir ulus devlet savaşla kurulmamıştır', 'Ulus devletler yalnız halkoylamalarıyla kurulmuştur', 'Savaşlar birliği hep geciktirmiştir'], 'İtalya 1859, 1860, 1866 ve 1870\'teki askerî gelişmelerle, Almanya ise 1864, 1866 ve 1870-1871 savaşlarıyla birleşti.'),
  ('Bir öğretmen \'Devrim kendi çocuklarını yer\' sözünü örneklemek istiyor. Aşağıdakilerden hangisi bu söze en uygun örnektir?', 'Danton ve Robespierre\'in devrim yıllarında giyotinle idam edilmesi', ['Napolyon\'un Saint Helena\'ya sürülmesi', 'XVIII. Louis\'nin tahta çıkması', 'Talleyrand\'ın uzun yıllar bakan kalması'], 'Devrimin önderleri birbirini tasfiye etti: Jirondenler, Hébert, Danton ve sonunda Robespierre giyotine gitti. Söz Jiroden Vergniaud\'ya atfedilir.'),
  ('Waterloo\'dan sonra Avrupa\'da 1815-1848 dönemi için \'Restorasyon dönemi\' adının kullanılması neyi vurgular?', 'Devrim öncesi hanedanların ve düzenin yeniden kurulmaya çalışılmasını', ['Yeni cumhuriyetlerin kurulması ve genel oyun yaygınlaşmasını', 'Sanayinin tamamen durmasını', 'Napolyon ailesinin iktidarını'], 'Restorasyon \'yeniden kurma\' demektir; meşru hanedanlar ve muhafazakâr düzen geri getirilmeye çalışıldı.'),
  ('Viyana Kongresi\'nde alınan kararlar ile 1871\'deki Avrupa haritası karşılaştırıldığında aşağıdaki devletlerden hangisi 1815\'te yoktu ama 1871\'de vardı?', 'Belçika', ['Prusya', 'Avusturya', 'İsveç'], 'Belçika 1830\'da bağımsızlığını ilan etti ve 1839\'da uluslararası olarak tanındı; diğerleri 1815\'te zaten vardı.'),
  ('Bastille\'in alınması askerî bakımdan küçük bir olay olduğu hâlde neden devrimin simgesi olmuştur?', 'Kraliyet despotizminin simgesi sayılan bir yapının halk tarafından ele geçirilmesi', ['Binlerce siyasi tutuklunun kurtarılması', 'Kralın orada tutuklanması', 'Fransız ordusunun yenilmesi'], 'Bastille\'de yalnız yedi tutuklu vardı; ancak keyfî tutuklamanın simgesi olan kalenin düşmesi mutlak monarşinin sarsıldığını gösterdi.'),
  ('Thermidor\'dan sonra Terör aygıtının dağıtılması ve Direktuvar\'ın kurulması, devrimin hangi evresine geçildiğini gösterir?', 'Radikallikten ılımlılığa dönüş evresine', ['Halk demokrasisinin doruğuna', 'Mutlak monarşinin ve feodal ayrıcalıkların geri gelişine', 'Kraliyetçilerin iktidarına'], 'Thermidor, devrimin radikal evresinin sonu olarak görülür; ardından mülk sahiplerinin düzenini önceleyen ılımlı bir cumhuriyet kuruldu.'),
  ('Napolyon\'un Konkordato ile Kilise\'yle uzlaşması, devrim döneminin hangi sorununu çözmeyi amaçlıyordu?', 'Din yüzünden bölünen toplumu yeniden barıştırmayı', ['Kilise topraklarını soylulara geri verip feodaliteyi canlandırmayı', 'Papanın Fransa\'yı yönetmesini sağlamayı', 'Protestanlığı yasaklamayı'], 'Ruhban Sivil Anayasası ve Hristiyanlıktan arındırma derin bir bölünme yaratmıştı; Konkordato Katolikleri rejime bağlayarak iç barışı amaçladı.'),
  ('Bir ülkenin yönetimi şu ilkelere dayanıyor: Kral meşru hanedandan, Kilise devletin dayanağı, basın sansürlü, gizli örgütler yasak. Bu tablo en çok hangi dönemi anlatır?', '1815 sonrası Metternich düzenini', ['1793 Jakoben cumhuriyetini', '1871 sonrası Fransız Üçüncü Cumhuriyeti\'ni', '1848 Frankfurt Parlamentosu\'nu'], 'Meşruiyet, taht-sunak ittifakı, sansür ve gizli örgütlere baskı Restorasyon ve Metternich sisteminin temel özellikleridir.'),
  ('Tahıl Yasaları\'nın kaldırılması İngiltere\'de hangi ekonomik anlayışın zaferi sayılır?', 'Serbest ticaret', ['Merkantilizm', 'Kıta Ablukası', 'Devlet tekelciliği'], 'Gümrüklerin kaldırılması, Adam Smith\'ten beri savunulan serbest ticaret anlayışının sanayici burjuvazinin desteğiyle kabul edilmesiydi.'),
];
